const e="16-02-2026",a="https://bcn.cl/jjuuJR",i="Contenido pedagógico abreviado. Consultar el texto oficial y el reglamento de cada condominio; algunas disposiciones tienen excepciones o modificaciones posteriores.",o=JSON.parse('[{"id":"L21442-A001","articulo":"1","referencia":"Artículo 1","tipo":"articulo_permanente","categoria":"Fundamentos y definiciones","titulo":"¿Qué es un condominio?","texto":"Un condominio puede ser de tipo A o B: en el tipo A compartes el terreno; en el tipo B puedes ser dueño exclusivo del sitio.","explicacion":"La copropiedad combina unidades de propiedad exclusiva con bienes comunes. La ley distingue condominios tipo A (unidades edificadas en terreno común) y tipo B (sitios urbanizados con bienes comunes).","precaucion":"No todo loteo rural se acoge a esta ley; existen requisitos específicos.","automatico":true,"pagina_inicio":1,"pagina_fin":3,"requiere_validacion":false},{"id":"L21442-A002","articulo":"2","referencia":"Artículo 2","tipo":"articulo_permanente","categoria":"Fundamentos y definiciones","titulo":"Conceptos esenciales","texto":"Los ascensores, techumbres, muros estructurales y redes generales suelen ser bienes comunes, aunque estén próximos a un departamento.","explicacion":"La ley define unidad, bienes comunes, asamblea, comité, administrador, subadministración, obligaciones económicas, gastos ordinarios y extraordinarios, fondo de reserva y copropietario hábil.","precaucion":"Distingue gastos comunes de mantención, reparación, administración y consumo.","automatico":true,"pagina_inicio":3,"pagina_fin":6,"requiere_validacion":false},{"id":"L21442-A003","articulo":"3","referencia":"Artículo 3","tipo":"articulo_permanente","categoria":"Derechos y obligaciones","titulo":"Propiedad y derechos comunes","texto":"Cuando vendes un departamento, también transfieres los derechos que le corresponden sobre los bienes comunes.","explicacion":"Ser dueño de una unidad implica participar también en los bienes comunes. Esos derechos están ligados a la unidad y su proporción se fija en el reglamento atendiendo al avalúo fiscal.","precaucion":"El porcentaje de participación puede variar de una unidad a otra.","automatico":true,"pagina_inicio":6,"pagina_fin":6,"requiere_validacion":false},{"id":"L21442-A004","articulo":"4","referencia":"Artículo 4","tipo":"articulo_permanente","categoria":"Derechos y obligaciones","titulo":"Uso de bienes comunes y convivencia","texto":"Dentro de un condominio residencial, la velocidad máxima en vías interiores para vehículos es de 30 km/h.","explicacion":"Propietarios y ocupantes pueden usar los bienes comunes respetando el reglamento y los derechos ajenos. En condominios residenciales las vías interiores vehiculares tienen velocidad máxima de 30 km/h.","precaucion":"Las normas de uso no pueden restringir arbitrariamente derechos legítimos.","automatico":true,"pagina_inicio":6,"pagina_fin":7,"requiere_validacion":false},{"id":"L21442-A005","articulo":"5","referencia":"Artículo 5","tipo":"articulo_permanente","categoria":"Derechos y obligaciones","titulo":"Registro y representación en asambleas","texto":"Si un propietario no designa representante ni asiste, el arrendatario u ocupante puede representarlo en ciertas condiciones.","explicacion":"Los copropietarios deben incorporarse al registro, informar domicilio y correo, y participar o hacerse representar en asambleas. La ley regula cuándo puede representarles el arrendatario u ocupante.","precaucion":"En materias de mayoría reforzada, el arrendatario necesita autorización expresa; el dueño puede excluir la representación supletoria.","automatico":true,"pagina_inicio":7,"pagina_fin":7,"requiere_validacion":false},{"id":"L21442-A006","articulo":"6","referencia":"Artículo 6","tipo":"articulo_permanente","categoria":"Derechos y obligaciones","titulo":"Obligaciones económicas y deudas anteriores","texto":"Al comprar una unidad, una deuda de gastos comunes anterior puede seguir afectando al nuevo dueño.","explicacion":"Los gastos y otras obligaciones se distribuyen según los derechos en bienes comunes, salvo regla distinta válida del reglamento. Las obligaciones siguen a la unidad incluso si se originaron antes de la compra.","precaucion":"Antes de comprar, solicita un certificado actualizado de deuda y revisa la escritura.","automatico":true,"pagina_inicio":7,"pagina_fin":8,"requiere_validacion":false},{"id":"L21442-A007","articulo":"7","referencia":"Artículo 7","tipo":"articulo_permanente","categoria":"Derechos y obligaciones","titulo":"Plazos de pago e intereses","texto":"Si el reglamento no establece otro plazo, los gastos comunes deben pagarse dentro de los diez días siguientes al aviso de cobro.","explicacion":"Como regla general, las obligaciones económicas se pagan dentro de los diez días siguientes a la emisión del aviso de cobro. El reglamento puede disponer otro plazo o periodicidad; hay límites legales para los intereses.","precaucion":"El interés por mora no puede superar el límite que señala este artículo.","automatico":true,"pagina_inicio":8,"pagina_fin":8,"requiere_validacion":false},{"id":"L21442-A008","articulo":"8","referencia":"Artículo 8","tipo":"articulo_permanente","categoria":"Reglamento de copropiedad","titulo":"Qué debe contener el reglamento","texto":"El reglamento no puede prohibir tener mascotas dentro de las unidades, pero sí puede regular su uso de espacios comunes.","explicacion":"El reglamento fija derechos, obligaciones, administración, multas, distribución de gastos, uso de bienes y convivencia, en consonancia con la ley y sin discriminación arbitraria.","precaucion":"También puede regular alojamientos temporales para proteger la convivencia.","automatico":true,"pagina_inicio":8,"pagina_fin":10,"requiere_validacion":false},{"id":"L21442-A009","articulo":"9","referencia":"Artículo 9","tipo":"articulo_permanente","categoria":"Reglamento de copropiedad","titulo":"El primer reglamento y entrega documental","texto":"Cuando se vende el 66% de las unidades de un condominio nuevo, el primer administrador debe convocar a una asamblea extraordinaria.","explicacion":"El propietario inicial dicta e inscribe el primer reglamento. Debe entregar antecedentes técnicos y administrativos al primer administrador. Vendido el 66% de unidades, corresponde convocar asamblea extraordinaria para rendir cuenta y decidir asuntos relevantes.","precaucion":"Entre los documentos exigibles están planos, permisos, manuales y carpetas de ascensores cuando corresponda.","automatico":true,"pagina_inicio":10,"pagina_fin":12,"requiere_validacion":false},{"id":"L21442-A010","articulo":"10","referencia":"Artículo 10","tipo":"articulo_permanente","categoria":"Reglamento de copropiedad","titulo":"Impugnar cláusulas contrarias a la ley","texto":"Una cláusula escrita en el reglamento no es automáticamente válida: puede ser anulada por un tribunal si infringe la ley.","explicacion":"Las cláusulas de un reglamento incompatibles con la ley, su reglamento o las características del condominio pueden ser anuladas judicialmente total o parcialmente, cumpliendo los requisitos legales.","precaucion":"La nulidad produce efectos cuando existe sentencia firme y requiere cumplir condiciones procesales.","automatico":true,"pagina_inicio":12,"pagina_fin":13,"requiere_validacion":false},{"id":"L21442-A011","articulo":"11","referencia":"Artículo 11","tipo":"articulo_permanente","categoria":"Reglamento de copropiedad","titulo":"Reglas supletorias","texto":"Que el reglamento interno guarde silencio no significa que el condominio quede sin reglas.","explicacion":"En materias que el reglamento de copropiedad no regula, rigen supletoriamente las disposiciones del reglamento de la ley.","precaucion":"Consulta también el reglamento de la ley y otras normas aplicables.","automatico":true,"pagina_inicio":13,"pagina_fin":13,"requiere_validacion":false},{"id":"L21442-A012","articulo":"12","referencia":"Artículo 12","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Órganos de administración","texto":"La asamblea, el comité y el administrador no cumplen la misma función ni tienen facultades intercambiables.","explicacion":"El régimen de administración reconoce a la asamblea, el comité de administración, el administrador y el subadministrador.","precaucion":"La subadministración aplica cuando existen sectores organizados conforme a la ley.","automatico":true,"pagina_inicio":13,"pagina_fin":13,"requiere_validacion":false},{"id":"L21442-A013","articulo":"13","referencia":"Artículo 13","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"La asamblea es el órgano decisorio principal","texto":"El principal órgano decisorio de un condominio es la asamblea de copropietarios, no el administrador.","explicacion":"La asamblea está formada por los propietarios y adopta decisiones vinculantes sobre administración, mantención, uso de bienes comunes y derechos y deberes de la comunidad.","precaucion":"Los acuerdos deben adoptarse con las formalidades y quórum que correspondan.","automatico":true,"pagina_inicio":13,"pagina_fin":13,"requiere_validacion":false},{"id":"L21442-A014","articulo":"14","referencia":"Artículo 14","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Asambleas ordinarias y extraordinarias","texto":"Copropietarios que representen el 10% de los derechos pueden solicitar una asamblea extraordinaria.","explicacion":"Debe celebrarse al menos una asamblea ordinaria al año, con cuenta documentada y balance. Algunas materias requieren asamblea extraordinaria; esta también puede solicitarse por copropietarios que representen al menos el 10% de derechos.","precaucion":"Entre las materias extraordinarias están ciertas inversiones, cambios de reglamento y obras.","automatico":true,"pagina_inicio":13,"pagina_fin":15,"requiere_validacion":false},{"id":"L21442-A015","articulo":"15","referencia":"Artículo 15","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Quórum, votos y actas","texto":"No todas las decisiones requieren la misma mayoría: ciertas materias exigen el voto del 66% de los derechos del condominio.","explicacion":"La ley diferencia quórum de constitución y de adopción de acuerdos: asambleas ordinarias, extraordinarias de mayoría absoluta y extraordinarias de mayoría reforzada del 66%. Permite consultas escritas y participación telemática bajo requisitos.","precaucion":"En una ordinaria se exige al menos el 33% de derechos para constituir y mayoría absoluta de asistentes para acordar; revisar siempre la materia.","automatico":true,"pagina_inicio":15,"pagina_fin":25,"requiere_validacion":true},{"id":"L21442-A016","articulo":"16","referencia":"Artículo 16","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Cómo convocar una asamblea","texto":"La citación a una asamblea normalmente debe hacerse entre 5 y 15 días antes de la sesión.","explicacion":"La citación debe enviarse a quienes correspondan por las vías legales con al menos cinco y no más de quince días de anticipación. Las sesiones pueden ser presenciales, telemáticas o mixtas.","precaucion":"Si se hace fuera del condominio, la sede de una sesión presencial o mixta debe estar en la misma comuna.","automatico":true,"pagina_inicio":25,"pagina_fin":26,"requiere_validacion":false},{"id":"L21442-A017","articulo":"17","referencia":"Artículo 17","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Comité: integración, plazo y reclamos","texto":"Una solicitud fundamentada ingresada al libro de novedades debe responderse dentro de 20 días corridos.","explicacion":"El comité tiene en general un número impar de tres a cinco integrantes, salvo excepciones. Su período no puede exceder tres años y debe responder las solicitudes asentadas en el libro de novedades dentro de veinte días corridos.","precaucion":"La ley prevé excepciones a la integración general del comité y mecanismos de sorteo si no hay interesados.","automatico":true,"pagina_inicio":26,"pagina_fin":27,"requiere_validacion":false},{"id":"L21442-A018","articulo":"18","referencia":"Artículo 18","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Designación y remoción del administrador","texto":"Una misma persona no puede ser a la vez administrador e integrante del comité de administración del mismo condominio.","explicacion":"El administrador es designado inicialmente por el propietario del proyecto y luego por la asamblea. Sus nombramientos deben documentarse legalmente. No puede integrar el comité y puede ser removido por la asamblea.","precaucion":"En ausencia del administrador, actúa el presidente del comité según la ley.","automatico":true,"pagina_inicio":27,"pagina_fin":28,"requiere_validacion":false},{"id":"L21442-A019","articulo":"19","referencia":"Artículo 19","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Administrador gratuito o remunerado","texto":"Aunque trabaje gratuitamente, el administrador también debe cumplir la exigencia legal de inscripción vigente en el Registro Nacional.","explicacion":"La labor de administración puede ser gratuita o remunerada, pero exige inscripción vigente en el Registro Nacional de Administradores conforme a la ley. El comité fija la remuneración u honorarios.","precaucion":"Las excepciones especiales, como ciertas designaciones provisionales, deben verificarse aparte.","automatico":true,"pagina_inicio":28,"pagina_fin":28,"requiere_validacion":false},{"id":"L21442-A020","articulo":"20","referencia":"Artículo 20","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Funciones y obligaciones del administrador","texto":"La ley obliga al administrador a gestionar mantenciones e inspecciones de instalaciones como gas y ascensores.","explicacion":"El administrador cuida bienes comunes, gestiona mantenimiento y certificaciones, recauda obligaciones, lleva contabilidad, convoca asambleas, gestiona seguridad y ejecuta las funciones legales y reglamentarias. Algunas decisiones requieren acuerdo del comité.","precaucion":"No puede suspender servicios a voluntad: existen condiciones, autorizaciones y prohibiciones específicas.","automatico":true,"pagina_inicio":28,"pagina_fin":30,"requiere_validacion":true},{"id":"L21442-A021","articulo":"21","referencia":"Artículo 21","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Rendición de cuentas mensual","texto":"El administrador debe rendir cuentas al comité todos los meses y exhibir los respaldos con al menos 24 horas de anticipación.","explicacion":"Debe rendirse cuenta documentada y detallada al comité todos los meses, ante la asamblea en sesiones ordinarias y al terminar la administración. Deben estar disponibles documentos de respaldo con al menos 24 horas de anticipación.","precaucion":"La rendición incluye ingresos, gastos, remuneraciones, cotizaciones, cartolas y seguros.","automatico":true,"pagina_inicio":30,"pagina_fin":30,"requiere_validacion":false},{"id":"L21442-A022","articulo":"22","referencia":"Artículo 22","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Presupuesto anual del condominio","texto":"El presupuesto de los próximos 12 meses debe remitirse con al menos 30 días de anticipación al período en que regirá.","explicacion":"El administrador debe proyectar ingresos y obligaciones económicas para doce meses, incluir el fondo de reserva e informar recargos previstos. Debe enviarlo al menos treinta días antes del período y permitir observaciones.","precaucion":"Es una proyección: los cobros mensuales se determinan según gastos y decisiones definitivas.","automatico":true,"pagina_inicio":30,"pagina_fin":31,"requiere_validacion":false},{"id":"L21442-A023","articulo":"23","referencia":"Artículo 23","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Qué es una subadministración","texto":"Un sector del condominio puede contar con subadministrador y subcomité para gestionar sus bienes y servicios comunes propios.","explicacion":"Un condominio con sectores puede establecer subadministraciones para resolver asuntos de bienes comunes propios de cada sector, sin perjudicar al conjunto. Deben definirse funciones y coordinación.","precaucion":"La subadministración no puede adoptar decisiones que afecten derechos de otros sectores.","automatico":true,"pagina_inicio":31,"pagina_fin":32,"requiere_validacion":false},{"id":"L21442-A024","articulo":"24","referencia":"Artículo 24","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Condominios de más de 200 viviendas","texto":"Los condominios de más de 200 viviendas tienen reglas especiales para organizar subadministraciones.","explicacion":"Los condominios con más de 200 unidades habitacionales deben organizar subadministraciones de hasta 200 unidades. Existe una excepción si el condominio consiste en una sola edificación colectiva, con exigencias diferenciadas.","precaucion":"En un único edificio de más de 200 viviendas se contempla una excepción, con medidas alternativas de gestión.","automatico":true,"pagina_inicio":32,"pagina_fin":32,"requiere_validacion":false},{"id":"L21442-A025","articulo":"25","referencia":"Artículo 25","tipo":"articulo_permanente","categoria":"Propiedad, bienes comunes y uso","titulo":"Hipotecas de unidades","texto":"Para hipotecar tu propia unidad no necesitas aprobación de la asamblea de copropietarios.","explicacion":"Una unidad puede hipotecarse sin requerir autorización de la asamblea. La hipoteca comprende sus derechos sobre los bienes comunes y puede constituirse también en etapa de proyecto, cumpliendo requisitos.","precaucion":"La hipoteca también alcanza los derechos de la unidad sobre bienes comunes.","automatico":true,"pagina_inicio":32,"pagina_fin":33,"requiere_validacion":false},{"id":"L21442-A026","articulo":"26","referencia":"Artículo 26","tipo":"articulo_permanente","categoria":"Propiedad, bienes comunes y uso","titulo":"Contratos sobre bienes comunes","texto":"Si el condominio obtiene dinero por arrendar un bien común, esos recursos incrementan el fondo común de reserva.","explicacion":"El arriendo, cesión, gravamen y eventual enajenación de bienes comunes requieren condiciones y acuerdos legales. Los ingresos obtenidos por estas operaciones incrementan el fondo común de reserva.","precaucion":"No todos los bienes comunes pueden venderse; algunos mantienen protección especial.","automatico":true,"pagina_inicio":33,"pagina_fin":34,"requiere_validacion":false},{"id":"L21442-A027","articulo":"27","referencia":"Artículo 27","tipo":"articulo_permanente","categoria":"Propiedad, bienes comunes y uso","titulo":"Uso permitido, ruidos y seguridad","texto":"El ruido molesto en horas de descanso y las conductas que comprometen la seguridad pueden generar sanciones legales.","explicacion":"Las unidades deben emplearse conforme a su destino. Se prohíben actos que perturben la tranquilidad, comprometan seguridad o salubridad, así como intervenciones de gas o ventilación sin los requisitos legales.","precaucion":"Las multas judiciales por estas infracciones pueden ir de 1 a 3 UTM, duplicables en caso de reincidencia.","automatico":true,"pagina_inicio":34,"pagina_fin":35,"requiere_validacion":false},{"id":"L21442-A028","articulo":"28","referencia":"Artículo 28","tipo":"articulo_permanente","categoria":"Propiedad, bienes comunes y uso","titulo":"Uso y goce exclusivo de un bien común","texto":"Que un residente use exclusivamente un patio común no significa que sea su propietario.","explicacion":"El uso exclusivo de ciertos bienes comunes requiere cumplir condiciones legales y del reglamento. Puede implicar pagos que ingresan al fondo de reserva y gastos de mantención de cargo del beneficiario.","precaucion":"La mantención del bien asignado puede corresponder al beneficiario, salvo norma o acuerdo diferente.","automatico":true,"pagina_inicio":35,"pagina_fin":35,"requiere_validacion":false},{"id":"L21442-A029","articulo":"29","referencia":"Artículo 29","tipo":"articulo_permanente","categoria":"Propiedad, bienes comunes y uso","titulo":"Obras en bienes de uso exclusivo","texto":"Un estacionamiento o terraza común asignado en uso exclusivo no puede remodelarse libremente solo por tener ese uso.","explicacion":"Tener uso y goce exclusivo no autoriza por sí solo a construir, modificar o cambiar el destino del bien común. Se requieren autorización reforzada y permisos cuando proceda.","precaucion":"Revisa autorización de asamblea y permisos municipales antes de intervenir.","automatico":true,"pagina_inicio":35,"pagina_fin":35,"requiere_validacion":false},{"id":"L21442-A030","articulo":"30","referencia":"Artículo 30","tipo":"articulo_permanente","categoria":"Propiedad, bienes comunes y uso","titulo":"Formalizar el uso exclusivo","texto":"Una asignación de uso y goce exclusivo sobre bienes comunes puede requerir inscripción en el Conservador de Bienes Raíces.","explicacion":"La asignación debe identificar la unidad beneficiaria. Las asignaciones que no figuren en el reglamento y recaigan sobre terrenos y bienes comunes deben inscribirse en el Conservador de Bienes Raíces.","precaucion":"La administración debe conservar copia de esas asignaciones.","automatico":true,"pagina_inicio":35,"pagina_fin":35,"requiere_validacion":false},{"id":"L21442-A031","articulo":"31","referencia":"Artículo 31","tipo":"articulo_permanente","categoria":"Gastos comunes, cobranza y fondos","titulo":"Qué debe informar el aviso de gastos comunes","texto":"El aviso de gastos comunes no debe mostrar solo el monto a pagar: también debe informar ingresos, egresos y saldo de caja de la comunidad.","explicacion":"El aviso de cobro debe detallar la participación del propietario, aportes al fondo de reserva, deudas por multas e intereses e información de ingresos, egresos y saldo de caja del condominio.","precaucion":"La proporción de contribución de la unidad debe constar en el aviso.","automatico":true,"pagina_inicio":35,"pagina_fin":36,"requiere_validacion":false},{"id":"L21442-A032","articulo":"32","referencia":"Artículo 32","tipo":"articulo_permanente","categoria":"Gastos comunes, cobranza y fondos","titulo":"El aviso firmado puede servir para cobrar judicialmente","texto":"Un aviso de cobro de gastos comunes firmado por el administrador puede servir como título ejecutivo para su cobro judicial.","explicacion":"Los avisos de cobro firmados presencial o electrónicamente por el administrador pueden tener mérito ejecutivo. La ley regula las acciones y notificaciones del procedimiento.","precaucion":"No significa embargo automático: se requiere el correspondiente procedimiento judicial.","automatico":true,"pagina_inicio":36,"pagina_fin":36,"requiere_validacion":false},{"id":"L21442-A033","articulo":"33","referencia":"Artículo 33","tipo":"articulo_permanente","categoria":"Gastos comunes, cobranza y fondos","titulo":"Cuenta bancaria exclusiva del condominio","texto":"Los dineros del condominio deben mantenerse en una cuenta bancaria exclusiva de la comunidad.","explicacion":"Todo condominio debe contar con cuenta corriente o de ahorro propia. Las personas autorizadas para girar son designadas por la asamblea y los cambios se formalizan conforme a la ley.","precaucion":"La cuenta no debe confundirse con la cuenta personal del administrador.","automatico":true,"pagina_inicio":36,"pagina_fin":36,"requiere_validacion":false},{"id":"L21442-A034","articulo":"34","referencia":"Artículo 34","tipo":"articulo_permanente","categoria":"Gastos comunes, cobranza y fondos","titulo":"Responsabilidad por impago dañino","texto":"Una deuda de gastos comunes puede generar responsabilidad adicional si causa perjuicios al condominio.","explicacion":"Si el impago de gastos comunes causa disminución del valor del condominio o riesgos no cubiertos por seguros, el copropietario incumplidor responde por los daños imputables.","precaucion":"Debe existir relación entre el incumplimiento y el daño reclamado.","automatico":true,"pagina_inicio":36,"pagina_fin":36,"requiere_validacion":false},{"id":"L21442-A035","articulo":"35","referencia":"Artículo 35","tipo":"articulo_permanente","categoria":"Gastos comunes, cobranza y fondos","titulo":"Unidad desocupada también paga","texto":"Aunque un departamento esté vacío, su propietario sigue obligado a pagar los gastos comunes correspondientes.","explicacion":"La ausencia de uso de un servicio común o la desocupación de una unidad no exime de contribuir a las obligaciones económicas comunes.","precaucion":"No utilizar piscina, ascensor u otros bienes tampoco elimina por sí solo la obligación.","automatico":true,"pagina_inicio":36,"pagina_fin":37,"requiere_validacion":false},{"id":"L21442-A036","articulo":"36","referencia":"Artículo 36","tipo":"articulo_permanente","categoria":"Gastos comunes, cobranza y fondos","titulo":"Cortes por mora y protecciones","texto":"Si en la unidad vive una persona electrodependiente, no se puede suspender la electricidad por mora de gastos comunes.","explicacion":"La ley regula la eventual suspensión de servicios cuando existan tres o más cuotas morosas, con acuerdo del comité y requisitos del administrador. No se pueden suspender simultáneamente varios servicios y existen protecciones especiales.","precaucion":"También hay restricciones por deudas originadas durante un estado de catástrofe vigente.","automatico":true,"pagina_inicio":37,"pagina_fin":37,"requiere_validacion":true},{"id":"L21442-A037","articulo":"37","referencia":"Artículo 37","tipo":"articulo_permanente","categoria":"Gastos comunes, cobranza y fondos","titulo":"Qué conceptos siguen las reglas de cobranza","texto":"Las reglas legales de cobranza no se limitan al gasto común base: pueden abarcar multas, intereses y fondo de reserva.","explicacion":"Las reglas de cobro, garantías y apremios de gastos comunes se extienden a intereses, multas y aportes al fondo común de reserva.","precaucion":"La aplicación debe respetar las normas y procedimientos pertinentes.","automatico":true,"pagina_inicio":37,"pagina_fin":37,"requiere_validacion":false},{"id":"L21442-A038","articulo":"38","referencia":"Artículo 38","tipo":"articulo_permanente","categoria":"Gastos comunes, cobranza y fondos","titulo":"Distribución de gastos por sectores","texto":"Un gasto por un servicio exclusivo de una torre puede distribuirse solo entre sus unidades si así lo regula el condominio.","explicacion":"Cuando existen bienes o servicios que sirven únicamente a un sector, el reglamento puede asignar esos gastos solo a sus copropietarios, sin liberarlos de gastos generales.","precaucion":"Los copropietarios del sector siguen contribuyendo a las obligaciones de todo el conjunto.","automatico":true,"pagina_inicio":37,"pagina_fin":37,"requiere_validacion":false},{"id":"L21442-A039","articulo":"39","referencia":"Artículo 39","tipo":"articulo_permanente","categoria":"Gastos comunes, cobranza y fondos","titulo":"Fondo común de reserva","texto":"Como regla general, el fondo de reserva debe recibir un recargo de al menos el 5% del gasto común mensual.","explicacion":"El fondo financia gastos extraordinarios, urgentes o imprevistos y contempla recursos para obligaciones por término de contratos laborales. El recargo general no puede ser inferior al 5% de los gastos comunes mensuales, con excepciones legales.","precaucion":"Los condominios de viviendas sociales pueden estar sujetos a reglas especiales.","automatico":true,"pagina_inicio":37,"pagina_fin":38,"requiere_validacion":true},{"id":"L21442-A040","articulo":"40","referencia":"Artículo 40","tipo":"articulo_permanente","categoria":"Seguridad, inspecciones y seguros","titulo":"Plan de emergencia y evacuación","texto":"El plan de evacuación debe actualizarse al menos una vez al año e incluir las necesidades de personas con movilidad reducida.","explicacion":"Todo condominio debe contar con plan de emergencia; el de evacuación se actualiza al menos una vez al año e incorpora necesidades de personas con discapacidad o movilidad reducida, menores y otros grupos. Los documentos deben estar disponibles en conserjería.","precaucion":"El plan actualizado debe mantenerse en conserjería y entregarse a Carabineros y Bomberos.","automatico":true,"pagina_inicio":38,"pagina_fin":39,"requiere_validacion":true},{"id":"L21442-A041","articulo":"41","referencia":"Artículo 41","tipo":"articulo_permanente","categoria":"Seguridad, inspecciones y seguros","titulo":"Facilitar revisiones dentro de las unidades","texto":"Una inspección técnica obligatoria puede requerir acceso a tu unidad; la ley exige facilitarla cuando corresponde.","explicacion":"Propietarios y ocupantes deben permitir revisiones o certificaciones exigidas por la normativa vigente, previa notificación en la forma legal.","precaucion":"El rechazo injustificado puede generar sanciones.","automatico":true,"pagina_inicio":39,"pagina_fin":40,"requiere_validacion":false},{"id":"L21442-A042","articulo":"42","referencia":"Artículo 42","tipo":"articulo_permanente","categoria":"Seguridad, inspecciones y seguros","titulo":"Acceso urgente ante emergencias","texto":"Ante una filtración o fuga grave y sin ocupantes disponibles, el administrador puede entrar forzadamente si se cumplen los requisitos legales.","explicacion":"Cuando filtraciones, inundaciones, emanaciones de gas u otros problemas comprometan la seguridad o conservación, el administrador puede acceder forzadamente a una unidad si no hay quien permita entrar, con acompañante y acta detallada.","precaucion":"Debe ir acompañado por un copropietario y dejar acta; no es autorización para ingresar por motivos ordinarios.","automatico":true,"pagina_inicio":40,"pagina_fin":40,"requiere_validacion":false},{"id":"L21442-A043","articulo":"43","referencia":"Artículo 43","tipo":"articulo_permanente","categoria":"Seguridad, inspecciones y seguros","titulo":"Seguro colectivo contra incendio","texto":"Aunque tengas seguro individual, sigues contribuyendo a la parte del seguro colectivo que protege los bienes comunes.","explicacion":"Los condominios que incluyen viviendas deben contar con un seguro colectivo contra incendios para bienes e instalaciones comunes, con opciones de cobertura de unidades. La ley regula mecanismos para evitar pagos duplicados.","precaucion":"Las coberturas adicionales, como sismo, no son automáticamente obligatorias por esta disposición.","automatico":true,"pagina_inicio":40,"pagina_fin":41,"requiere_validacion":true},{"id":"L21442-A044","articulo":"44","referencia":"Artículo 44","tipo":"articulo_permanente","categoria":"Resolución de conflictos","titulo":"Conflictos ante el Juzgado de Policía Local","texto":"Un Juzgado de Policía Local puede revisar determinados acuerdos de asamblea contrarios a la Ley de Copropiedad.","explicacion":"Los juzgados de policía local conocen diversas controversias sobre administración y funcionamiento del condominio y pueden adoptar medidas, como invalidar acuerdos contrarios a la ley o citar asambleas.","precaucion":"La competencia y acciones concretas dependen del tipo de controversia.","automatico":true,"pagina_inicio":41,"pagina_fin":42,"requiere_validacion":false},{"id":"L21442-A045","articulo":"45","referencia":"Artículo 45","tipo":"articulo_permanente","categoria":"Resolución de conflictos","titulo":"Apelación de resoluciones judiciales","texto":"Una decisión judicial en conflictos de copropiedad puede ser apelable según el procedimiento legal.","explicacion":"Las resoluciones dictadas en las gestiones de copropiedad reguladas por el artículo anterior son apelables bajo las normas de la Ley 18.287.","precaucion":"Los requisitos y plazos concretos se determinan por la normativa procesal aplicable.","automatico":false,"pagina_inicio":42,"pagina_fin":43,"requiere_validacion":false},{"id":"L21442-A046","articulo":"46","referencia":"Artículo 46","tipo":"articulo_permanente","categoria":"Resolución de conflictos","titulo":"Solución de conflictos por arbitraje","texto":"Ciertas disputas de copropiedad pueden resolverse mediante arbitraje y no exclusivamente ante el Juzgado de Policía Local.","explicacion":"Algunas controversias de copropiedad pueden someterse a un juez árbitro de acuerdo con las condiciones legales. La designación puede ser por acuerdo o, en su defecto, judicial.","precaucion":"El arbitraje sigue reglas específicas sobre nombramiento y recursos.","automatico":true,"pagina_inicio":43,"pagina_fin":43,"requiere_validacion":false},{"id":"L21442-A047","articulo":"47","referencia":"Artículo 47","tipo":"articulo_permanente","categoria":"Resolución de conflictos","titulo":"Mediación municipal extrajudicial","texto":"La municipalidad puede intervenir para buscar una solución amistosa a conflictos de un condominio.","explicacion":"La municipalidad puede atender conflictos que no se hayan solucionado previamente en asamblea, citar a las partes y proponer acuerdos, salvo cuando el asunto esté sometido a juez o árbitro.","precaucion":"No puede actuar en ese conflicto si una parte ya recurrió al tribunal o al árbitro.","automatico":true,"pagina_inicio":43,"pagina_fin":43,"requiere_validacion":false},{"id":"L21442-A048","articulo":"48","referencia":"Artículo 48","tipo":"articulo_permanente","categoria":"Constitución legal de condominios","titulo":"Constitución legal del condominio","texto":"No basta con tener varios departamentos: el régimen de copropiedad requiere el certificado correspondiente de la Dirección de Obras Municipales.","explicacion":"Para acogerse a la copropiedad se requieren cumplimiento urbanístico, primer reglamento e intervención de la Dirección de Obras Municipales, que certifica el régimen. La documentación se conserva en un expediente municipal.","precaucion":"Los proyectos en construcción tienen reglas especiales para comercializar unidades.","automatico":true,"pagina_inicio":43,"pagina_fin":45,"requiere_validacion":false},{"id":"L21442-A049","articulo":"49","referencia":"Artículo 49","tipo":"articulo_permanente","categoria":"Constitución legal de condominios","titulo":"Planos de copropiedad","texto":"Los planos oficiales permiten identificar qué es unidad privada y qué es bien común dentro del condominio.","explicacion":"Los planos deben identificar cada unidad, los sectores y bienes comunes; requieren aprobación municipal y archivo en el Conservador de Bienes Raíces.","precaucion":"Los planos deben archivarse junto con el certificado del régimen de copropiedad.","automatico":false,"pagina_inicio":45,"pagina_fin":45,"requiere_validacion":false},{"id":"L21442-A050","articulo":"50","referencia":"Artículo 50","tipo":"articulo_permanente","categoria":"Constitución legal de condominios","titulo":"Escrituras y referencia a planos","texto":"La escritura de venta de una unidad debe remitir al plano oficial del condominio.","explicacion":"Las escrituras de transferencia o constitución de derechos reales deben identificar el plano de copropiedad y, en la primera transferencia, insertar el certificado pertinente.","precaucion":"Esa identificación ayuda a precisar qué unidad y derechos se transfieren.","automatico":false,"pagina_inicio":45,"pagina_fin":45,"requiere_validacion":false},{"id":"L21442-A051","articulo":"51","referencia":"Artículo 51","tipo":"articulo_permanente","categoria":"Constitución legal de condominios","titulo":"Inscripción de propiedad de cada unidad","texto":"La inscripción de dominio debe identificar el número y la ubicación de la unidad según el plano de copropiedad.","explicacion":"La inscripción conservatoria incluye datos del título, partes, condominio y la unidad individualizada en el plano, con formalidades exigidas por la normativa.","precaucion":"Los deslindes del condominio también forman parte de sus menciones.","automatico":false,"pagina_inicio":45,"pagina_fin":46,"requiere_validacion":false},{"id":"L21442-A052","articulo":"52","referencia":"Artículo 52","tipo":"articulo_permanente","categoria":"Constitución legal de condominios","titulo":"Modificar o terminar el régimen","texto":"La Dirección de Obras Municipales no puede dejar sin efecto, por sí sola, el régimen de copropiedad ya declarado.","explicacion":"La Dirección de Obras Municipales no puede revocar unilateralmente la declaración de copropiedad. La asamblea puede solicitar modificarla o dejarla sin efecto cumpliendo requisitos urbanísticos y autorizaciones aplicables.","precaucion":"Los acreedores hipotecarios u otros titulares de derechos pueden tener que autorizar cambios.","automatico":true,"pagina_inicio":46,"pagina_fin":46,"requiere_validacion":false},{"id":"L21442-A053","articulo":"53","referencia":"Artículo 53","tipo":"articulo_permanente","categoria":"Constitución legal de condominios","titulo":"Plazo municipal para resolver","texto":"La Dirección de Obras Municipales dispone de 30 días corridos para pronunciarse en las solicitudes a que se refieren los artículos 48 y 52.","explicacion":"El director de obras municipales tiene treinta días corridos para pronunciarse sobre solicitudes de acogimiento o modificación del régimen reguladas en los artículos indicados.","precaucion":"La ley remite también a procedimientos especiales de urbanismo y construcciones.","automatico":false,"pagina_inicio":46,"pagina_fin":46,"requiere_validacion":false},{"id":"L21442-A054","articulo":"54","referencia":"Artículo 54","tipo":"articulo_permanente","categoria":"Exigencias urbanas y de construcción","titulo":"Superficie mínima y tipos de predios","texto":"Una unidad de un condominio tipo B puede ser más pequeña que la subdivisión predial mínima, bajo condiciones sobre la superficie total del conjunto.","explicacion":"Se permite acogerse al régimen en ciertos predios existentes menores al mínimo de subdivisión. Para sitios tipo B la ley fija una forma especial de calcular superficies.","precaucion":"No es un permiso general para dividir cualquier terreno.","automatico":false,"pagina_inicio":46,"pagina_fin":46,"requiere_validacion":false},{"id":"L21442-A055","articulo":"55","referencia":"Artículo 55","tipo":"articulo_permanente","categoria":"Exigencias urbanas y de construcción","titulo":"Trama vial y conectividad urbana","texto":"El diseño de un condominio no puede ignorar las exigencias de conectividad y trama vial de su entorno.","explicacion":"Los nuevos condominios deben respetar la planificación de vías y, en los casos previstos, integrar vías públicas o proyectar circulaciones para no impedir la conectividad. Hay excepciones municipales fundadas.","precaucion":"El texto fue modificado en febrero de 2026: conviene distinguir la regla vigente de versiones antiguas.","automatico":false,"pagina_inicio":46,"pagina_fin":47,"requiere_validacion":true},{"id":"L21442-A056","articulo":"56","referencia":"Artículo 56","tipo":"articulo_permanente","categoria":"Exigencias urbanas y de construcción","titulo":"Normas para construir en sitios tipo B","texto":"Ser dueño del sitio en un condominio tipo B no permite construir sin respetar las normas urbanísticas.","explicacion":"En sitios de propiedad exclusiva de condominios tipo B las construcciones deben cumplir el plan regulador y normas de urbanismo y construcción aplicables.","precaucion":"Siempre revisa uso de suelo, permisos y reglas del condominio.","automatico":false,"pagina_inicio":47,"pagina_fin":47,"requiere_validacion":false},{"id":"L21442-A057","articulo":"57","referencia":"Artículo 57","tipo":"articulo_permanente","categoria":"Exigencias urbanas y de construcción","titulo":"Potencial constructivo pendiente","texto":"El potencial de construcción que queda en un condominio puede repartirse proporcionalmente a los derechos en bienes comunes.","explicacion":"Si el condominio no ocupó toda la capacidad edificatoria disponible, su distribución entre unidades se determina según derechos sobre los bienes comunes.","precaucion":"No debe confundirse con una autorización automática para ampliar.","automatico":false,"pagina_inicio":47,"pagina_fin":47,"requiere_validacion":false},{"id":"L21442-A058","articulo":"58","referencia":"Artículo 58","tipo":"articulo_permanente","categoria":"Exigencias urbanas y de construcción","titulo":"Prohibición de subdividir sitios y terrenos","texto":"No puedes subdividir libremente tu sitio dentro de un condominio tipo B.","explicacion":"Como regla general, los terrenos comunes y los sitios exclusivos de condominios no pueden subdividirse o lotearse mientras exista el condominio, salvo las circunstancias previstas por la ley.","precaucion":"La ley remite a excepciones asociadas a bienes comunes y condiciones especiales.","automatico":false,"pagina_inicio":47,"pagina_fin":48,"requiere_validacion":false},{"id":"L21442-A059","articulo":"59","referencia":"Artículo 59","tipo":"articulo_permanente","categoria":"Exigencias urbanas y de construcción","titulo":"Circulaciones y vehículos de emergencia","texto":"La ley contempla un máximo de 400 metros de recorrido peatonal por circulaciones comunes desde un acceso al condominio hasta unidades o edificaciones.","explicacion":"Las vías y accesos internos deben cumplir condiciones urbanísticas y permitir operación de vehículos de emergencia. El acceso peatonal por circulaciones comunes no puede exceder 400 metros desde un acceso, en los supuestos previstos.","precaucion":"No deben instalarse elementos que obstruyan la circulación de vehículos de emergencia.","automatico":true,"pagina_inicio":48,"pagina_fin":48,"requiere_validacion":false},{"id":"L21442-A060","articulo":"60","referencia":"Artículo 60","tipo":"articulo_permanente","categoria":"Exigencias urbanas y de construcción","titulo":"Estacionamientos y accesibilidad","texto":"Los estacionamientos de visita son bienes comunes: no pueden venderse ni asignarse en uso y goce exclusivo.","explicacion":"La ley regula estacionamientos para vehículos y bicicletas, cuotas mínimas en viviendas de interés público, restricciones de venta y asignación, espacios para personas con discapacidad y estacionamientos de visita.","precaucion":"Las cuotas de estacionamientos en viviendas de interés público tienen excepciones legales y transitorias.","automatico":true,"pagina_inicio":48,"pagina_fin":50,"requiere_validacion":true},{"id":"L21442-A061","articulo":"61","referencia":"Artículo 61","tipo":"articulo_permanente","categoria":"Obras, cambios y subdivisión","titulo":"Representación ante Obras Municipales","texto":"Para solicitar obras a nombre de la comunidad ante la municipalidad, se debe justificar legalmente quién la representa.","explicacion":"Las solicitudes de permisos y autorizaciones del condominio ante la Dirección de Obras Municipales deben acreditar quién tiene facultad para representarlo.","precaucion":"La facultad puede provenir del reglamento, un acta o un mandato especial.","automatico":false,"pagina_inicio":50,"pagina_fin":50,"requiere_validacion":false},{"id":"L21442-A062","articulo":"62","referencia":"Artículo 62","tipo":"articulo_permanente","categoria":"Obras, cambios y subdivisión","titulo":"Cambio de destino de una unidad","texto":"Convertir una vivienda en local comercial puede requerir tanto permiso municipal como acuerdo previo de la asamblea.","explicacion":"Cambiar el uso autorizado de una unidad requiere compatibilidad con la planificación urbana, permiso de la Dirección de Obras Municipales y acuerdo previo de asamblea.","precaucion":"El nuevo destino debe estar permitido por el instrumento de planificación territorial.","automatico":true,"pagina_inicio":50,"pagina_fin":50,"requiere_validacion":false},{"id":"L21442-A063","articulo":"63","referencia":"Artículo 63","tipo":"articulo_permanente","categoria":"Obras, cambios y subdivisión","titulo":"Demolición de un condominio","texto":"Si se decreta legalmente la demolición de un condominio, su futuro debe tratarse en asamblea extraordinaria.","explicacion":"Si la municipalidad decreta la demolición conforme a la ley, la asamblea extraordinaria debe acordar cómo proceder.","precaucion":"La orden municipal y los acuerdos deben seguir los procedimientos aplicables.","automatico":false,"pagina_inicio":50,"pagina_fin":50,"requiere_validacion":false},{"id":"L21442-A064","articulo":"64","referencia":"Artículo 64","tipo":"articulo_permanente","categoria":"Obras, cambios y subdivisión","titulo":"Subdividir un condominio existente","texto":"Para aprobar una propuesta de subdivisión de condominio, la ley contempla un quórum de al menos 66% de los derechos.","explicacion":"La subdivisión requiere resolución de la Dirección de Obras Municipales, el cumplimiento urbanístico aplicable y aprobación bajo requisitos legales; una propuesta de copropietarios requiere al menos 66% de los derechos.","precaucion":"Los condominios de viviendas sociales tienen vías y exenciones adicionales.","automatico":true,"pagina_inicio":50,"pagina_fin":51,"requiere_validacion":false},{"id":"L21442-A065","articulo":"65","referencia":"Artículo 65","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Régimen de viviendas de interés público","texto":"No todas las normas generales se aplican igual a los condominios de viviendas de interés público.","explicacion":"Estos condominios se rigen primero por reglas especiales del Título XII y, en lo no previsto o no contradictorio, por las reglas generales.","precaucion":"Antes de aplicar un porcentaje o exigencia, verifica si el Título XII contiene una excepción.","automatico":false,"pagina_inicio":51,"pagina_fin":51,"requiere_validacion":false},{"id":"L21442-A066","articulo":"66","referencia":"Artículo 66","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Qué viviendas se consideran de interés público","texto":"Un condominio de interés público y uno de viviendas sociales no son exactamente la misma categoría jurídica.","explicacion":"El título define conjuntos vinculados a financiamiento o programas habitacionales del MINVU y condominios de viviendas sociales según sus características y antecedentes.","precaucion":"La ley precisa los casos y antecedentes que permiten clasificarlos.","automatico":false,"pagina_inicio":51,"pagina_fin":52,"requiere_validacion":false},{"id":"L21442-A067","articulo":"67","referencia":"Artículo 67","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Cómo acreditar vivienda social o de interés público","texto":"La calificación como condominio de vivienda social puede acreditarse mediante un certificado de la Dirección de Obras Municipales.","explicacion":"La condición puede documentarse mediante resolución ministerial de interés público o certificado municipal de vivienda social, según el supuesto legal.","precaucion":"La vía de acreditación depende del tipo de condominio y sus antecedentes.","automatico":false,"pagina_inicio":52,"pagina_fin":53,"requiere_validacion":false},{"id":"L21442-A068","articulo":"68","referencia":"Artículo 68","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Ayudas y programas públicos","texto":"Los apoyos públicos para condominios sociales pueden destinarse también a mantención o certificación de ascensores y capacitación de comités.","explicacion":"Municipios, gobiernos regionales y SERVIU pueden financiar proyectos para condominios de viviendas sociales en materias como reparación, seguros, mantención, capacitación, convivencia y equipos de circulación vertical.","precaucion":"Postular o ser elegible no garantiza la asignación de recursos.","automatico":true,"pagina_inicio":53,"pagina_fin":54,"requiere_validacion":false},{"id":"L21442-A069","articulo":"69","referencia":"Artículo 69","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Formalizar reglamentos en vivienda social","texto":"Un condominio de viviendas sociales sin reglamento inscrito puede formalizar el primero mediante el procedimiento legal especial.","explicacion":"Los condominios de viviendas sociales que no tengan reglamento inscrito pueden formalizarlo utilizando el quórum que la ley determina para esa materia.","precaucion":"La aprobación debe cumplir el quórum que remite al artículo 15.","automatico":false,"pagina_inicio":54,"pagina_fin":54,"requiere_validacion":false},{"id":"L21442-A070","articulo":"70","referencia":"Artículo 70","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Límite de viviendas sociales nuevas","texto":"Para proyectos nuevos de vivienda social rige un límite de 160 unidades habitacionales por condominio, sujeto a excepciones.","explicacion":"Desde el 1 de enero de 2024 los nuevos condominios de viviendas sociales no pueden contar con más de 160 viviendas, con excepciones transitorias para proyectos en determinados estados de avance.","precaucion":"El artículo transitorio 11 exceptúa proyectos que cumplían ciertos hitos al 1 de enero de 2024.","automatico":true,"pagina_inicio":54,"pagina_fin":55,"requiere_validacion":true},{"id":"L21442-A071","articulo":"71","referencia":"Artículo 71","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Registro municipal para condominios sociales","texto":"Las municipalidades deben llevar antecedentes identificables de los condominios de viviendas sociales de su comuna.","explicacion":"Los municipios deben incorporar condominios sociales en un apartado específico de su registro y custodiar copias de documentos relevantes conforme a la ley.","precaucion":"Los originales o documentos de gobierno también tienen reglas de custodia comunitaria.","automatico":false,"pagina_inicio":55,"pagina_fin":55,"requiere_validacion":false},{"id":"L21442-A072","articulo":"72","referencia":"Artículo 72","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Medidores individuales y gastos de consumo","texto":"En condominios de viviendas sociales, los cobros de gastos comunes efectuados por empresas de servicios deben emitirse en documento separado.","explicacion":"En viviendas sociales, las empresas de servicios deben dotar medidores individuales y pueden realizar cobros de gastos comunes bajo convenios, con documentos separados cuando corresponda.","precaucion":"La ley también establece reglas para medidores individuales.","automatico":false,"pagina_inicio":55,"pagina_fin":56,"requiere_validacion":false},{"id":"L21442-A073","articulo":"73","referencia":"Artículo 73","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Exenciones notariales y municipales","texto":"Los condominios de viviendas sociales tienen exenciones legales en diversas gestiones notariales y conservatorias obligatorias.","explicacion":"Determinadas actuaciones necesarias para cumplir la ley están exentas de aranceles de notarios, conservadores y archiveros en condominios sociales, bajo acreditación y formalidades.","precaucion":"Se debe acreditar oficialmente la condición de vivienda social.","automatico":true,"pagina_inicio":56,"pagina_fin":56,"requiere_validacion":false},{"id":"L21442-A074","articulo":"74","referencia":"Artículo 74","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Subadministraciones en viviendas de interés público","texto":"Las reglas de subadministración también pueden ser exigibles en condominios de viviendas de interés público.","explicacion":"El régimen de subadministraciones de los artículos 23 y 24 también se aplica a los condominios de viviendas de interés público.","precaucion":"La organización sectorial debe respetar los derechos del conjunto.","automatico":false,"pagina_inicio":56,"pagina_fin":56,"requiere_validacion":false},{"id":"L21442-A075","articulo":"75","referencia":"Artículo 75","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Reserva especial en viviendas sociales","texto":"El recargo general del 5% para fondo de reserva puede tener excepciones en condominios de viviendas sociales.","explicacion":"El fondo de reserva de condominios sociales se sujeta a reglas especiales del reglamento de la ley, que puede exceptuar el recargo mínimo o periodicidad general en determinados supuestos.","precaucion":"No se debe aplicar automáticamente la regla general sin revisar la norma especial.","automatico":true,"pagina_inicio":56,"pagina_fin":56,"requiere_validacion":true},{"id":"L21442-A076","articulo":"76","referencia":"Artículo 76","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Mediación municipal para interés público","texto":"En condominios de viviendas de interés público, la municipalidad tiene deberes especiales de mediación y asesoría.","explicacion":"La municipalidad debe actuar como instancia de mediación extrajudicial en conflictos de condominios de viviendas de interés público y asesorar la organización de los copropietarios.","precaucion":"Es diferente de la facultad general de mediación municipal del artículo 47.","automatico":false,"pagina_inicio":56,"pagina_fin":57,"requiere_validacion":false},{"id":"L21442-A077","articulo":"77","referencia":"Artículo 77","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Educación municipal sobre copropiedad social","texto":"La ley obliga a las municipalidades a impulsar educación sobre derechos y deberes en condominios de viviendas sociales.","explicacion":"Los municipios deben desarrollar programas educativos y ofrecer apoyo y asesoría para que los residentes de viviendas sociales conozcan sus derechos y deberes.","precaucion":"También permite apoyo jurídico, técnico y contable en determinados casos.","automatico":true,"pagina_inicio":57,"pagina_fin":57,"requiere_validacion":false},{"id":"L21442-A078","articulo":"78","referencia":"Artículo 78","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Apoyo municipal al funcionamiento","texto":"Un condominio de vivienda social puede solicitar asesoría municipal para gestiones relacionadas con cobro de gastos comunes.","explicacion":"Los municipios, directamente o en convenio, deben apoyar trámites para el funcionamiento de condominios sociales, incluida asesoría para cobranza judicial y regularización de conjuntos antiguos.","precaucion":"La ley contempla apoyo para adaptar conjuntos antiguos al régimen.","automatico":false,"pagina_inicio":57,"pagina_fin":57,"requiere_validacion":false},{"id":"L21442-A079","articulo":"79","referencia":"Artículo 79","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Densificación predial","texto":"Los proyectos especiales de densificación predial pueden llegar hasta 12 viviendas en ciertos programas MINVU, sujetos a condiciones.","explicacion":"La ley regula condominios pequeños en un mismo predio, con hasta cuatro nuevas viviendas o tres adicionales cuando ya existe una, destinados a programas habitacionales. Algunos programas MINVU pueden alcanzar hasta 12 unidades con densidad límite.","precaucion":"No es una autorización general para construir doce viviendas en cualquier terreno.","automatico":true,"pagina_inicio":57,"pagina_fin":58,"requiere_validacion":false},{"id":"L21442-A080","articulo":"80","referencia":"Artículo 80","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Exenciones en densificación predial","texto":"Un condominio de densificación predial de hasta cuatro viviendas está exceptuado de varias exigencias generales de administración y seguridad.","explicacion":"Estos condominios no requieren comité ni administrador; los de hasta cuatro viviendas tampoco requieren fondo de reserva, estacionamientos, seguros ni plan de emergencia, según esta norma especial.","precaucion":"No confundas esta excepción legal específica con todos los condominios pequeños.","automatico":true,"pagina_inicio":58,"pagina_fin":58,"requiere_validacion":false},{"id":"L21442-A081","articulo":"81","referencia":"Artículo 81","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Decisiones en densificación predial","texto":"En densificación predial, las decisiones comunes deben coordinarse entre copropietarios, aunque no exista administrador.","explicacion":"Los copropietarios gestionan conjuntamente las materias que afecten más de una unidad. La Dirección de Obras puede autorizar algunas obras de seguridad a solicitud de un afectado.","precaucion":"Para ciertas obras de seguridad o habitabilidad basta solicitar autorización municipal por un afectado.","automatico":false,"pagina_inicio":58,"pagina_fin":58,"requiere_validacion":false},{"id":"L21442-A082","articulo":"82","referencia":"Artículo 82","tipo":"articulo_permanente","categoria":"Registro Nacional de Administradores","titulo":"Registro Nacional de Administradores","texto":"El Registro Nacional de Administradores de Condominios es público, obligatorio y gratuito.","explicacion":"Se crea un registro público, obligatorio y gratuito de quienes administran condominios, a cargo del Ministerio de Vivienda y Urbanismo.","precaucion":"Su finalidad es identificar y supervisar a quienes ejercen la administración.","automatico":true,"pagina_inicio":58,"pagina_fin":58,"requiere_validacion":false},{"id":"L21442-A083","articulo":"83","referencia":"Artículo 83","tipo":"articulo_permanente","categoria":"Registro Nacional de Administradores","titulo":"Inscripción para ejercer","texto":"La inscripción en el Registro Nacional es requisito previo para administrar condominios, incluso de manera gratuita.","explicacion":"Como regla general, para ejercer como administrador o subadministrador se requiere inscripción previa en el Registro Nacional, aun si el servicio se presta gratis.","precaucion":"Existen disposiciones transitorias o especiales que deben revisarse cuando corresponda.","automatico":true,"pagina_inicio":58,"pagina_fin":59,"requiere_validacion":false},{"id":"L21442-A084","articulo":"84","referencia":"Artículo 84","tipo":"articulo_permanente","categoria":"Registro Nacional de Administradores","titulo":"Requisitos de los administradores","texto":"Quien cobra por administrar debe cumplir requisitos de formación o certificación, además de las demás exigencias legales.","explicacion":"La ley contempla inhabilidades penales y, para servicios remunerados, requisitos de enseñanza media y formación o certificación laboral. Regula también personas jurídicas y personas naturales que ejecutan la administración.","precaucion":"En personas jurídicas, al menos un socio o representante legal cumple requisitos, y quien efectivamente administra debe estar inscrito.","automatico":true,"pagina_inicio":59,"pagina_fin":59,"requiere_validacion":false},{"id":"L21442-A085","articulo":"85","referencia":"Artículo 85","tipo":"articulo_permanente","categoria":"Registro Nacional de Administradores","titulo":"Registro digital y sanciones","texto":"El registro ministerial puede mostrar sanciones impuestas a administradores inscritos.","explicacion":"La inscripción se gestiona en la plataforma ministerial. El Registro identifica administradores, condominios atendidos y sanciones, así como altas y bajas.","precaucion":"Esto ayuda a evaluar antecedentes antes de contratar.","automatico":true,"pagina_inicio":59,"pagina_fin":59,"requiere_validacion":false},{"id":"L21442-A086","articulo":"86","referencia":"Artículo 86","tipo":"articulo_permanente","categoria":"Registro Nacional de Administradores","titulo":"Reglamentación de la actividad","texto":"Las exigencias operativas del Registro Nacional se complementan mediante un reglamento ministerial.","explicacion":"Un reglamento ministerial determina procedimientos y condiciones de inscripción y funcionamiento del Registro, distinguiendo servicios gratuitos y remunerados.","precaucion":"La ley no fija por sí sola todos los trámites de inscripción.","automatico":false,"pagina_inicio":59,"pagina_fin":60,"requiere_validacion":false},{"id":"L21442-A087","articulo":"87","referencia":"Artículo 87","tipo":"articulo_permanente","categoria":"Infracciones, sanciones y reclamos","titulo":"Tipos de infracciones del administrador","texto":"Proporcionar antecedentes falsos sobre la gestión de un condominio puede ser una infracción gravísima.","explicacion":"La ley clasifica incumplimientos en gravísimos, graves, menos graves y leves según la conducta y reincidencia. Incluye, por ejemplo, falsedad de antecedentes y omisiones de seguridad.","precaucion":"La clasificación importa porque determina las posibles sanciones administrativas.","automatico":true,"pagina_inicio":60,"pagina_fin":61,"requiere_validacion":true},{"id":"L21442-A088","articulo":"88","referencia":"Artículo 88","tipo":"articulo_permanente","categoria":"Infracciones, sanciones y reclamos","titulo":"Sanciones al administrador","texto":"Un administrador puede ser eliminado del Registro Nacional por una infracción gravísima.","explicacion":"Las infracciones gravísimas pueden generar eliminación del Registro y/o multa de 5 a 10 UTM; las graves, suspensión de uno a tres años y/o multa de 5 a 10 UTM. Existen sanciones menores.","precaucion":"Las multas y suspensiones dependen de la clasificación de la infracción.","automatico":true,"pagina_inicio":61,"pagina_fin":61,"requiere_validacion":true},{"id":"L21442-A089","articulo":"89","referencia":"Artículo 89","tipo":"articulo_permanente","categoria":"Infracciones, sanciones y reclamos","titulo":"Cómo se gradúa una sanción","texto":"Una infracción que ponga en riesgo vidas puede recibir una evaluación más severa que otra sin esas consecuencias.","explicacion":"Al sancionar, la autoridad considera riesgos a personas, derechos afectados, gastos extraordinarios causados y perjuicios económicos.","precaucion":"La autoridad debe considerar los efectos reales del incumplimiento.","automatico":false,"pagina_inicio":61,"pagina_fin":62,"requiere_validacion":false},{"id":"L21442-A090","articulo":"90","referencia":"Artículo 90","tipo":"articulo_permanente","categoria":"Infracciones, sanciones y reclamos","titulo":"Quién puede reclamar ante la SEREMI","texto":"El comité y, bajo condiciones, grupos de propietarios o arrendatarios pueden reclamar contra el administrador ante la SEREMI.","explicacion":"El comité o un porcentaje reglamentario de copropietarios o arrendatarios puede reclamar ante la SEREMI por incumplimientos del administrador, indicando hechos y aportando respaldos.","precaucion":"La reclamación debe describir acciones u omisiones y acompañar pruebas.","automatico":true,"pagina_inicio":62,"pagina_fin":62,"requiere_validacion":false},{"id":"L21442-A091","articulo":"91","referencia":"Artículo 91","tipo":"articulo_permanente","categoria":"Infracciones, sanciones y reclamos","titulo":"Inicio del procedimiento sancionatorio","texto":"Un administrador acusado en un procedimiento sancionatorio tiene 10 días hábiles para presentar descargos.","explicacion":"La SEREMI puede desestimar la reclamación, pedir información o iniciar cargos. El administrador investigado tiene diez días hábiles para presentar descargos desde su notificación.","precaucion":"El procedimiento exige formular cargos y notificar los antecedentes.","automatico":true,"pagina_inicio":62,"pagina_fin":62,"requiere_validacion":false},{"id":"L21442-A092","articulo":"92","referencia":"Artículo 92","tipo":"articulo_permanente","categoria":"Infracciones, sanciones y reclamos","titulo":"Investigación de la reclamación","texto":"Una denuncia no implica sanción automática: la SEREMI puede investigar y reunir pruebas.","explicacion":"La SEREMI debe evaluar antecedentes y puede ordenar diligencias para verificar incumplimientos y sus efectos antes de resolver.","precaucion":"La gravedad se determina a partir de hechos y consecuencias acreditadas.","automatico":false,"pagina_inicio":62,"pagina_fin":62,"requiere_validacion":false},{"id":"L21442-A093","articulo":"93","referencia":"Artículo 93","tipo":"articulo_permanente","categoria":"Infracciones, sanciones y reclamos","titulo":"Plazo para dictar resolución","texto":"La SEREMI tiene 30 días hábiles desde la última diligencia para dictar resolución en el procedimiento.","explicacion":"La resolución de reclamación debe emitirse dentro de treinta días hábiles desde la última diligencia ordenada.","precaucion":"El plazo no se cuenta necesariamente desde la presentación inicial de la reclamación.","automatico":false,"pagina_inicio":62,"pagina_fin":63,"requiere_validacion":false},{"id":"L21442-A094","articulo":"94","referencia":"Artículo 94","tipo":"articulo_permanente","categoria":"Infracciones, sanciones y reclamos","titulo":"Recursos contra sanciones","texto":"Una sanción administrativa contra el administrador puede impugnarse mediante reposición dentro de 5 días hábiles.","explicacion":"Frente a sanciones de la SEREMI procede reposición, dentro de cinco días hábiles; también se regula recurso jerárquico ante la Subsecretaría de Vivienda y Urbanismo.","precaucion":"Existen reglas específicas si se presenta además un recurso jerárquico.","automatico":false,"pagina_inicio":63,"pagina_fin":63,"requiere_validacion":false},{"id":"L21442-A095","articulo":"95","referencia":"Artículo 95","tipo":"articulo_permanente","categoria":"Infracciones, sanciones y reclamos","titulo":"Evitar duplicación de reclamaciones","texto":"Si reclamas ante la SEREMI, no puedes llevar la misma pretensión contra el administrador a la municipalidad o al Juzgado de Policía Local.","explicacion":"Quien interpone reclamación ante la SEREMI no puede presentar la misma pretensión contra ese administrador simultáneamente ante el Juzgado de Policía Local o la municipalidad.","precaucion":"La restricción se refiere al mismo reclamante y la misma pretensión.","automatico":false,"pagina_inicio":63,"pagina_fin":63,"requiere_validacion":false},{"id":"L21442-A096","articulo":"96","referencia":"Artículo 96","tipo":"articulo_permanente","categoria":"Infracciones, sanciones y reclamos","titulo":"Prescripción de reclamaciones","texto":"Existe un plazo de prescripción de dos años para reclamar administrativamente ciertas conductas del administrador.","explicacion":"Las reclamaciones contra administradores y subadministradores prescriben a los dos años desde la acción u omisión reclamada.","precaucion":"El plazo se cuenta desde la acción u omisión, no necesariamente desde que descubriste el hecho.","automatico":false,"pagina_inicio":63,"pagina_fin":63,"requiere_validacion":false},{"id":"L21442-A097","articulo":"97","referencia":"Artículo 97","tipo":"articulo_permanente","categoria":"Disposiciones finales","titulo":"Quién interpreta y coordina la ley","texto":"El Ministerio de Vivienda publica circulares que orientan la aplicación de la Ley de Copropiedad.","explicacion":"El MINVU imparte instrucciones mediante circulares y la Secretaría Ejecutiva de Condominios mantiene registros y coordina tareas. La SEREMI interviene en ciertas reclamaciones municipales.","precaucion":"Las SEREMI también supervisan ciertas decisiones de las Direcciones de Obras Municipales.","automatico":false,"pagina_inicio":63,"pagina_fin":64,"requiere_validacion":false},{"id":"L21442-A098","articulo":"98","referencia":"Artículo 98","tipo":"articulo_permanente","categoria":"Disposiciones finales","titulo":"Registro de condominios habitacionales","texto":"Además del registro de administradores, existe un registro de condominios habitacionales.","explicacion":"Los condominios con viviendas deben estar incorporados a un registro con datos de ubicación, viviendas, expediente y reglamento; la información se alimenta desde la Dirección de Obras Municipales.","precaucion":"La Secretaría Ejecutiva de Condominios lo alimenta a partir de información municipal.","automatico":true,"pagina_inicio":64,"pagina_fin":64,"requiere_validacion":false},{"id":"L21442-A099","articulo":"99","referencia":"Artículo 99","tipo":"articulo_permanente","categoria":"Disposiciones finales","titulo":"Comunidades acogidas a leyes antiguas","texto":"Los derechos de uso y goce exclusivo constituidos legalmente antes de esta ley no desaparecen por el solo cambio normativo.","explicacion":"Se establecen reglas de continuidad para condominios regidos anteriormente por propiedad horizontal y para ciertos derechos preexistentes de uso exclusivo.","precaucion":"La aplicación a comunidades antiguas contiene salvaguardas y excepciones específicas.","automatico":false,"pagina_inicio":64,"pagina_fin":65,"requiere_validacion":false},{"id":"L21442-A100","articulo":"100","referencia":"Artículo 100","tipo":"articulo_permanente","categoria":"Disposiciones finales","titulo":"Sustitución de la antigua ley","texto":"La entrada en vigencia de la Ley 21.442 no anuló automáticamente los acuerdos de asambleas anteriores.","explicacion":"La Ley 21.442 derogó la Ley 19.537, con reglas interpretativas y transitorias. Los reglamentos de copropiedad deben ajustarse, pero acuerdos anteriores no quedan sin efecto automáticamente.","precaucion":"El plazo de actualización de reglamentos tiene reglas legales y una nota interpretativa vinculada al reglamento de la ley.","automatico":false,"pagina_inicio":65,"pagina_fin":65,"requiere_validacion":false},{"id":"L21442-A101","articulo":"101","referencia":"Artículo 101","tipo":"articulo_permanente","categoria":"Disposiciones finales","titulo":"Referencias a la legislación anterior","texto":"Si un documento legal antiguo dice junta de vigilancia, la Ley 21.442 remite a la figura del comité de administración.","explicacion":"Las referencias legales a la normativa derogada se entienden hechas a las nuevas disposiciones correspondientes; la antigua expresión junta de vigilancia equivale a comité de administración.","precaucion":"La norma facilita la continuidad interpretativa de referencias legales.","automatico":false,"pagina_inicio":65,"pagina_fin":65,"requiere_validacion":false},{"id":"L21442-A102","articulo":"102","referencia":"Artículo 102","tipo":"articulo_permanente","categoria":"Disposiciones finales","titulo":"Condominio con dueño único o pocos propietarios","texto":"Un condominio acogido a la ley sigue sujeto a ella aunque todavía no haya vendido todas sus unidades.","explicacion":"La ley se aplica aunque las unidades todavía pertenezcan al dueño original. Si todas están bajo un dueño o hay menos de tres copropietarios, se sustituyen ciertas funciones del comité. Con menos del 33% de derechos vendidos se contempla asamblea anual de residentes.","precaucion":"Si los derechos vendidos son menores al 33%, la ley contempla una asamblea anual informativa de residentes.","automatico":true,"pagina_inicio":65,"pagina_fin":66,"requiere_validacion":false},{"id":"L21442-T1","articulo":"T1","referencia":"Artículo 1 transitorio","tipo":"articulo_transitorio","categoria":"Disposiciones transitorias y otras reformas","titulo":"Reglamentos antiguos y reglamento tipo","texto":"Los condominios antiguos pueden quedar sometidos al reglamento tipo cuando no formalizan el suyo en el plazo previsto.","explicacion":"Los condominios comprendidos en esta transición deben dotarse de reglamento. Si no se dicta en el plazo legal se aplica el reglamento tipo ministerial; la modificación del texto señala efectos retroactivos.","precaucion":"Es una norma transitoria; para casos actuales debe verificarse el cómputo y normativa aplicable.","automatico":false,"pagina_inicio":66,"pagina_fin":66,"requiere_validacion":true},{"id":"L21442-T2","articulo":"T2","referencia":"Artículo 2 transitorio","tipo":"articulo_transitorio","categoria":"Disposiciones transitorias y otras reformas","titulo":"Plazo transitorio de administradores antiguos","texto":"La ley contempló una transición especial para administradores que ya ejercían cuando se aprobó el nuevo régimen.","explicacion":"Se permitía continuar temporalmente a quienes acreditaran tres meses en el cargo mientras se implementaba el Registro. Luego se estableció un plazo de dieciocho meses para capacitación o certificación y registro.","precaucion":"Dato histórico: los plazos deben contrastarse con la fecha efectiva de entrada en vigencia del Registro.","automatico":false,"pagina_inicio":66,"pagina_fin":67,"requiere_validacion":true},{"id":"L21442-T3","articulo":"T3","referencia":"Artículo 3 transitorio","tipo":"articulo_transitorio","categoria":"Disposiciones transitorias y otras reformas","titulo":"Postulación de condominios sociales sin organizar","texto":"Un condominio social aún no organizado puede acceder a determinadas postulaciones públicas con firmas que representen al menos 50% de los derechos.","explicacion":"Condominios de viviendas sociales no organizados pueden postular a ciertos programas públicos mediante firmas de copropietarios que representen al menos la mitad de derechos, con representación autorizada.","precaucion":"La norma establece formas especiales para autorizar representación.","automatico":true,"pagina_inicio":67,"pagina_fin":67,"requiere_validacion":false},{"id":"L21442-T4","articulo":"T4","referencia":"Artículo 4 transitorio","tipo":"articulo_transitorio","categoria":"Disposiciones transitorias y otras reformas","titulo":"Norma técnica de emergencia","texto":"El plan de emergencia debe cumplir además una norma técnica oficial, no solo una lista informal de instrucciones.","explicacion":"La elaboración y actualización de los planes de emergencia y evacuación deben respetar la norma técnica que oficialice el MINVU.","precaucion":"Revisar la norma técnica vigente antes de elaborar o actualizar.","automatico":true,"pagina_inicio":67,"pagina_fin":67,"requiere_validacion":false},{"id":"L21442-T5","articulo":"T5","referencia":"Artículo 5 transitorio","tipo":"articulo_transitorio","categoria":"Disposiciones transitorias y otras reformas","titulo":"Transición de seguro de incendio","texto":"La obligatoriedad del nuevo seguro colectivo tuvo un período de adaptación legal.","explicacion":"La exigibilidad del nuevo seguro colectivo se difirió seis meses desde la publicación del reglamento y se reguló un plazo de dos años para revisar pólizas anteriores.","precaucion":"Es información transitoria y no debe anunciarse como un plazo nuevo para todos los condominios.","automatico":false,"pagina_inicio":67,"pagina_fin":67,"requiere_validacion":true},{"id":"L21442-T6","articulo":"T6","referencia":"Artículo 6 transitorio","tipo":"articulo_transitorio","categoria":"Disposiciones transitorias y otras reformas","titulo":"Dictación de reglamentos","texto":"La ley exigió una consulta pública de al menos 30 días para sus reglamentos de implementación.","explicacion":"La ley ordenó dictar los reglamentos de la ley y del Registro de Administradores en doce meses, con consulta pública mínima de treinta días.","precaucion":"Se trata de un hito legislativo de implementación, no de un plazo periódico para las comunidades.","automatico":false,"pagina_inicio":67,"pagina_fin":67,"requiere_validacion":true},{"id":"L21442-T7","articulo":"T7","referencia":"Artículo 7 transitorio","tipo":"articulo_transitorio","categoria":"Disposiciones transitorias y otras reformas","titulo":"Financiamiento fiscal inicial","texto":"La ley especificó cómo financiar el gasto fiscal de su primer año de aplicación.","explicacion":"El mayor gasto del primer año presupuestario se cargaría al presupuesto MINVU y subsidiariamente a Tesoro Público.","precaucion":"Es una disposición presupuestaria histórica, no una fuente de financiamiento automático para condominios.","automatico":false,"pagina_inicio":67,"pagina_fin":67,"requiere_validacion":true},{"id":"L21442-T8","articulo":"T8","referencia":"Artículo 8 transitorio","tipo":"articulo_transitorio","categoria":"Disposiciones transitorias y otras reformas","titulo":"Aplicación transitoria de estacionamientos","texto":"La nueva exigencia de estacionamientos tiene excepciones para proyectos que ya contaban con avances definidos al 1 de enero de 2025.","explicacion":"La exigencia de estacionamientos para nuevos condominios de interés público se aplica a proyectos que soliciten permiso desde el 1 de enero de 2025, con excepciones por subsidio o avance y posible rebaja de hasta 50% de la exigencia del plan regulador en esos casos.","precaucion":"En esas excepciones, la cantidad exigida por el plan regulador puede rebajarse hasta 50% según la regla legal.","automatico":false,"pagina_inicio":67,"pagina_fin":68,"requiere_validacion":true},{"id":"L21442-T9","articulo":"T9","referencia":"Artículo 9 transitorio","tipo":"articulo_transitorio","categoria":"Disposiciones transitorias y otras reformas","titulo":"Artículo transitorio derogado","texto":"El artículo noveno transitorio fue derogado: no debe mostrarse como una obligación vigente.","explicacion":"El noveno artículo transitorio consta expresamente como derogado en la versión adjunta de la ley.","precaucion":"Conservar solo como referencia legislativa, sin notificación automática.","automatico":false,"pagina_inicio":68,"pagina_fin":68,"requiere_validacion":true},{"id":"L21442-T10","articulo":"T10","referencia":"Artículo 10 transitorio","tipo":"articulo_transitorio","categoria":"Disposiciones transitorias y otras reformas","titulo":"Plazo inicial de registro de condominios","texto":"La ley fijó un plazo inicial de dos años para inscribir en su registro los condominios habitacionales existentes al publicarse.","explicacion":"Los condominios con unidades habitacionales existentes al publicarse la ley tenían dos años para su incorporación al registro del artículo 98.","precaucion":"Plazo histórico; no presentarlo como si empezara hoy.","automatico":false,"pagina_inicio":68,"pagina_fin":68,"requiere_validacion":true},{"id":"L21442-T11","articulo":"T11","referencia":"Artículo 11 transitorio","tipo":"articulo_transitorio","categoria":"Disposiciones transitorias y otras reformas","titulo":"Excepción al tope de 160 viviendas sociales","texto":"Determinados proyectos iniciados antes del 1 de enero de 2024 quedan exceptuados del límite de 160 viviendas sociales.","explicacion":"El límite de 160 viviendas sociales nuevas no se exige a ciertos proyectos que al 1 de enero de 2024 ya tenían subsidio asignado, evaluación SERVIU o anteproyecto o permiso tramitado conforme a la ley.","precaucion":"Verificar los hitos y documentos indicados en la disposición transitoria.","automatico":false,"pagina_inicio":68,"pagina_fin":68,"requiere_validacion":true},{"id":"L21442-SEGUNDO","articulo":"SEGUNDO","referencia":"Artículo segundo","tipo":"reforma_legal","categoria":"Disposiciones transitorias y otras reformas","titulo":"Reformas vinculadas a urbanismo y construcción","texto":"La Ley 21.442 también modificó la Ley General de Urbanismo y Construcciones en materias de seguridad y planes de emergencia.","explicacion":"El artículo segundo de la Ley 21.442 modificó disposiciones de la Ley General de Urbanismo y Construcciones relacionadas con responsabilidad técnica, seguridad y terminología de planes de emergencia.","precaucion":"Contiene cuatro modificaciones legales, separadas del articulado principal de copropiedad.","automatico":true,"pagina_inicio":68,"pagina_fin":69,"requiere_validacion":false},{"id":"L21442-A002-D01","articulo":"2","referencia":"Artículo 2","tipo":"articulo_permanente","categoria":"Fundamentos y definiciones","titulo":"¿Qué incluye el gasto ordinario?","texto":"No todo cobro alto es extraordinario; la ley define cuatro categorías de gastos ordinarios.","explicacion":"Los gastos comunes ordinarios abarcan administración, mantención, reparación y servicios colectivos de uso o consumo.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":3,"pagina_fin":6,"requiere_validacion":false},{"id":"L21442-A002-D02","articulo":"2","referencia":"Artículo 2","tipo":"articulo_permanente","categoria":"Fundamentos y definiciones","titulo":"Fondo operacional inicial","texto":"El fondo operacional inicial es distinto del fondo común de reserva.","explicacion":"El fondo operacional inicial sirve para cubrir los gastos de puesta en marcha del condominio.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":3,"pagina_fin":6,"requiere_validacion":false},{"id":"L21442-A005-D01","articulo":"5","referencia":"Artículo 5","tipo":"articulo_permanente","categoria":"Derechos y obligaciones","titulo":"Representación reforzada","texto":"No basta la representación supletoria en todas las votaciones de asamblea.","explicacion":"En votaciones que requieren mayoría reforzada, el arrendatario u ocupante necesita autorización expresa del propietario.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":7,"pagina_fin":7,"requiere_validacion":false},{"id":"L21442-A006-D01","articulo":"6","referencia":"Artículo 6","tipo":"articulo_permanente","categoria":"Derechos y obligaciones","titulo":"Convenios de pago y habilidad","texto":"Firmar un convenio no basta: debe pagarse la primera cuota y cumplirse los pagos.","explicacion":"Un moroso con convenio de pago aprobado por el comité recupera calidad de copropietario hábil desde que paga la primera cuota y cumple el acuerdo y las otras obligaciones.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":7,"pagina_fin":8,"requiere_validacion":false},{"id":"L21442-A006-D02","articulo":"6","referencia":"Artículo 6","tipo":"articulo_permanente","categoria":"Derechos y obligaciones","titulo":"Copropietarios de una unidad","texto":"La copropiedad de un departamento no divide automáticamente la deuda frente al condominio.","explicacion":"Si una unidad pertenece a varias personas, cada una es solidariamente responsable de la totalidad de las obligaciones económicas.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":7,"pagina_fin":8,"requiere_validacion":false},{"id":"L21442-A007-D01","articulo":"7","referencia":"Artículo 7","tipo":"articulo_permanente","categoria":"Derechos y obligaciones","titulo":"Límite de intereses","texto":"El reglamento del edificio no puede fijar libremente cualquier interés por atraso.","explicacion":"La tasa moratoria del reglamento no puede superar el 50% del interés corriente bancario.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":8,"pagina_fin":8,"requiere_validacion":false},{"id":"L21442-A008-D01","articulo":"8","referencia":"Artículo 8","tipo":"articulo_permanente","categoria":"Reglamento de copropiedad","titulo":"Alojamiento temporal","texto":"Los alojamientos de corta estadía deben respetar normas de convivencia del condominio.","explicacion":"El reglamento debe incorporar normas de convivencia y sanciones para evitar molestias por alojamientos temporales u hospedaje turístico.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":8,"pagina_fin":10,"requiere_validacion":false},{"id":"L21442-A008-D02","articulo":"8","referencia":"Artículo 8","tipo":"articulo_permanente","categoria":"Reglamento de copropiedad","titulo":"Discriminación laboral","texto":"Las reglas sobre espacios comunes no pueden discriminar arbitrariamente por la actividad laboral del residente.","explicacion":"Se prohíbe limitar bienes comunes con discriminaciones arbitrarias fundadas en condiciones laborales, incluso invocando emergencias.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":8,"pagina_fin":10,"requiere_validacion":false},{"id":"L21442-A009-D01","articulo":"9","referencia":"Artículo 9","tipo":"articulo_permanente","categoria":"Reglamento de copropiedad","titulo":"Información previa a comprar","texto":"Tienes derecho a conocer el primer reglamento antes de firmar la promesa de compraventa.","explicacion":"El propietario inicial debe entregar copia digital y material del primer reglamento antes de la promesa de venta o compraventa.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":10,"pagina_fin":12,"requiere_validacion":false},{"id":"L21442-A009-D02","articulo":"9","referencia":"Artículo 9","tipo":"articulo_permanente","categoria":"Reglamento de copropiedad","titulo":"Telecomunicaciones sin exclusividad","texto":"El condominio no puede asegurar una exclusividad indebida a una sola empresa de telecomunicaciones.","explicacion":"El primer reglamento no puede impedir el acceso de empresas de telecomunicaciones ni pactar exclusividad en las condiciones prohibidas.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":10,"pagina_fin":12,"requiere_validacion":false},{"id":"L21442-A009-D03","articulo":"9","referencia":"Artículo 9","tipo":"articulo_permanente","categoria":"Reglamento de copropiedad","titulo":"Entrega técnica de instalaciones","texto":"El primer administrador debe recibir información técnica de las instalaciones comunes.","explicacion":"El archivo del condominio debe contemplar carpetas técnicas, planos y manuales, y carpeta de ascensores cuando corresponda.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":10,"pagina_fin":12,"requiere_validacion":false},{"id":"L21442-A009-D04","articulo":"9","referencia":"Artículo 9","tipo":"articulo_permanente","categoria":"Reglamento de copropiedad","titulo":"Primer administrador y acta","texto":"La entrega de un edificio nuevo implica documentar el estado de sus instalaciones comunes.","explicacion":"Antes de que ingrese el primer copropietario, el primer administrador debe levantar acta del estado de instalaciones comunes en la forma reglamentaria.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":10,"pagina_fin":12,"requiere_validacion":false},{"id":"L21442-A014-D01","articulo":"14","referencia":"Artículo 14","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Observaciones al balance","texto":"La administración dispone de 15 días corridos para responder observaciones al balance presentadas por copropietarios.","explicacion":"Si hay observaciones al balance en asamblea ordinaria, el administrador debe responderlas en un máximo de quince días corridos.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":13,"pagina_fin":15,"requiere_validacion":false},{"id":"L21442-A014-D02","articulo":"14","referencia":"Artículo 14","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Gastos de seis cuotas","texto":"Ciertas inversiones grandes requieren tratarse en asamblea extraordinaria.","explicacion":"Los gastos o inversiones extraordinarias que superen en 12 meses el equivalente a seis cuotas de gastos comunes ordinarios del total del condominio son materia extraordinaria.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":13,"pagina_fin":15,"requiere_validacion":false},{"id":"L21442-A015-D01","articulo":"15","referencia":"Artículo 15","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Votar desde casa","texto":"Las asambleas virtuales son posibles cuando el reglamento cumple condiciones legales.","explicacion":"El reglamento puede permitir sesiones telemáticas si resguarda participación y votación efectiva y simultánea.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":15,"pagina_fin":25,"requiere_validacion":true},{"id":"L21442-A015-D02","articulo":"15","referencia":"Artículo 15","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Consultas por escrito","texto":"No todas las decisiones requieren presencialidad: algunas pueden adoptarse mediante consulta por escrito.","explicacion":"La ley contempla votaciones por escrito con antecedentes, sesión informativa e identificación verificable de quienes participan.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":15,"pagina_fin":25,"requiere_validacion":true},{"id":"L21442-A015-D03","articulo":"15","referencia":"Artículo 15","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Solo propietarios hábiles votan","texto":"Una deuda pendiente puede afectar la posibilidad de votar y optar a cargos de representación.","explicacion":"La ley limita el voto y la postulación a cargos a copropietarios hábiles; su calidad se acredita mediante certificado de administración.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":15,"pagina_fin":25,"requiere_validacion":true},{"id":"L21442-A015-D04","articulo":"15","referencia":"Artículo 15","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Actas en 30 días","texto":"Las actas de asamblea deben formalizarse dentro de 30 días de la adopción del acuerdo.","explicacion":"Las actas deben firmarse, presencial o electrónicamente, a más tardar dentro de treinta días siguientes al acuerdo.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":15,"pagina_fin":25,"requiere_validacion":true},{"id":"L21442-A015-D05","articulo":"15","referencia":"Artículo 15","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Administrador no representa","texto":"El administrador no puede votar en nombre de un dueño como representante de éste.","explicacion":"El administrador no puede representar a un copropietario en asamblea.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":15,"pagina_fin":25,"requiere_validacion":true},{"id":"L21442-A017-D01","articulo":"17","referencia":"Artículo 17","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Sorteo del comité","texto":"La falta de voluntarios no impide necesariamente formar un comité: existe sorteo.","explicacion":"Si no hay interesados o no se logra acuerdo para integrar el comité, la ley contempla designación por sorteo.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":26,"pagina_fin":27,"requiere_validacion":false},{"id":"L21442-A017-D02","articulo":"17","referencia":"Artículo 17","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Libro de novedades","texto":"El libro de novedades es también un canal formal para reclamos y solicitudes fundadas.","explicacion":"El presidente del comité tiene obligaciones específicas de custodia documental y de poner a disposición el libro de novedades.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":26,"pagina_fin":27,"requiere_validacion":false},{"id":"L21442-A020-D01","articulo":"20","referencia":"Artículo 20","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Certificación de ascensores","texto":"No basta que un ascensor funcione: la ley exige gestionar su mantención y certificación.","explicacion":"El administrador puede contratar mantención y certificación de ascensores con las formalidades y comunicación al comité exigidas.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":28,"pagina_fin":30,"requiere_validacion":true},{"id":"L21442-A020-D02","articulo":"20","referencia":"Artículo 20","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Gas: respuesta en 10 días hábiles","texto":"El comité dispone de 10 días hábiles para responder una propuesta de verificación de gas.","explicacion":"Al notificarse una propuesta de verificación de gas, el comité tiene diez días hábiles para aceptarla o plantear alternativa.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":28,"pagina_fin":30,"requiere_validacion":true},{"id":"L21442-A020-D03","articulo":"20","referencia":"Artículo 20","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Simulacros","texto":"Los simulacros de evacuación forman parte de la gestión legal de seguridad del condominio.","explicacion":"Entre los antecedentes de seguridad que se informan a la autoridad figuran la realización de simulacros anuales de evacuación.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":28,"pagina_fin":30,"requiere_validacion":true},{"id":"L21442-A021-D01","articulo":"21","referencia":"Artículo 21","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Qué debe incluir la rendición","texto":"Una rendición de cuentas completa debe mostrar respaldos, no solo un resumen de cifras.","explicacion":"La rendición debe mostrar ingresos, egresos, remuneraciones, pagos previsionales, saldos bancarios, cartolas y seguro contratado.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":30,"pagina_fin":30,"requiere_validacion":false},{"id":"L21442-A022-D01","articulo":"22","referencia":"Artículo 22","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Plazo para observar presupuesto","texto":"Puedes observar el presupuesto anual hasta 15 días antes del inicio de su período de aplicación.","explicacion":"Los copropietarios pueden presentar observaciones al presupuesto hasta quince días antes del inicio del período previsto.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":30,"pagina_fin":31,"requiere_validacion":false},{"id":"L21442-A023-D01","articulo":"23","referencia":"Artículo 23","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Representación de sectores","texto":"Una torre no debería quedar sin representación en el comité general si existe subadministración por sectores.","explicacion":"El comité general debe integrar al menos un representante de cada sector cuando el condominio está dividido en subadministraciones.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":31,"pagina_fin":32,"requiere_validacion":false},{"id":"L21442-A026-D01","articulo":"26","referencia":"Artículo 26","tipo":"articulo_permanente","categoria":"Propiedad, bienes comunes y uso","titulo":"Ingresos de bienes comunes","texto":"Arrendar bienes comunes puede ayudar a fortalecer el fondo de reserva.","explicacion":"Los recursos provenientes de ciertos contratos y actos sobre bienes comunes incrementan el fondo de reserva.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":33,"pagina_fin":34,"requiere_validacion":false},{"id":"L21442-A027-D01","articulo":"27","referencia":"Artículo 27","tipo":"articulo_permanente","categoria":"Propiedad, bienes comunes y uso","titulo":"Reincidencia en seis meses","texto":"Una infracción de convivencia reiterada dentro del período legal puede duplicar su multa.","explicacion":"Para las multas del artículo 27, la misma infracción cometida dentro de seis meses desde la sentencia anterior constituye reincidencia.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":34,"pagina_fin":35,"requiere_validacion":false},{"id":"L21442-A027-D02","articulo":"27","referencia":"Artículo 27","tipo":"articulo_permanente","categoria":"Propiedad, bienes comunes y uso","titulo":"Plazo para denunciar","texto":"La ley contempla tres meses para denunciar judicialmente ciertas infracciones de convivencia.","explicacion":"El comité, el administrador o un afectado pueden denunciar las infracciones del artículo 27 dentro de tres meses desde el hecho.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":34,"pagina_fin":35,"requiere_validacion":false},{"id":"L21442-A031-D01","articulo":"31","referencia":"Artículo 31","tipo":"articulo_permanente","categoria":"Gastos comunes, cobranza y fondos","titulo":"Transparencia de egresos","texto":"Tu boleta de gastos comunes debe ayudar a entender en qué se gastó el dinero comunitario.","explicacion":"La ley requiere que el aviso de cobro informe ingresos y egresos mensuales totales y el saldo de caja del condominio.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":35,"pagina_fin":36,"requiere_validacion":false},{"id":"L21442-A032-D01","articulo":"32","referencia":"Artículo 32","tipo":"articulo_permanente","categoria":"Gastos comunes, cobranza y fondos","titulo":"Firma electrónica en cobro","texto":"Los avisos digitales de gastos comunes pueden respaldar judicialmente una deuda.","explicacion":"La firma electrónica del administrador puede dar mérito ejecutivo al aviso de cobro si cumple requisitos.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":36,"pagina_fin":36,"requiere_validacion":false},{"id":"L21442-A036-D01","articulo":"36","referencia":"Artículo 36","tipo":"articulo_permanente","categoria":"Gastos comunes, cobranza y fondos","titulo":"Solo un servicio a la vez","texto":"Aunque existan tres cuotas impagas, la ley no permite cortar varios servicios simultáneamente.","explicacion":"Por la mora, no se puede efectuar ni solicitar suspensión simultánea de más de uno de los servicios regulados.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":37,"pagina_fin":37,"requiere_validacion":true},{"id":"L21442-A039-D01","articulo":"39","referencia":"Artículo 39","tipo":"articulo_permanente","categoria":"Gastos comunes, cobranza y fondos","titulo":"Multas alimentan la reserva","texto":"Las multas por incumplimientos no son ingresos personales del administrador.","explicacion":"Las multas e intereses que correspondan ingresan al fondo común de reserva.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":37,"pagina_fin":38,"requiere_validacion":true},{"id":"L21442-A039-D02","articulo":"39","referencia":"Artículo 39","tipo":"articulo_permanente","categoria":"Gastos comunes, cobranza y fondos","titulo":"Reserva para finiquitos","texto":"El fondo de reserva también debe prever obligaciones por término de contratos laborales.","explicacion":"El fondo debe contemplar una parte proporcional de recursos para pagos asociados al término de contratos de trabajadores.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":37,"pagina_fin":38,"requiere_validacion":true},{"id":"L21442-A040-D01","articulo":"40","referencia":"Artículo 40","tipo":"articulo_permanente","categoria":"Seguridad, inspecciones y seguros","titulo":"Bomberos y Carabineros","texto":"El plan de emergencia actualizado debe compartirse formalmente con Bomberos y Carabineros.","explicacion":"El plan y sus actualizaciones deben entregarse en formato material y digital a Bomberos y Carabineros competentes.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":38,"pagina_fin":39,"requiere_validacion":true},{"id":"L21442-A040-D02","articulo":"40","referencia":"Artículo 40","tipo":"articulo_permanente","categoria":"Seguridad, inspecciones y seguros","titulo":"Plan firmado por especialista","texto":"El plan de emergencia no debería ser un documento improvisado sin responsable técnico.","explicacion":"El plan de emergencia y sus actualizaciones deben ser elaborados y suscritos por ingeniero en prevención de riesgos, con otras firmas para las actualizaciones.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":38,"pagina_fin":39,"requiere_validacion":true},{"id":"L21442-A040-D03","articulo":"40","referencia":"Artículo 40","tipo":"articulo_permanente","categoria":"Seguridad, inspecciones y seguros","titulo":"Accesibilidad en evacuaciones","texto":"Las rutas y procedimientos de evacuación deben considerar a quienes necesitan apoyos especiales.","explicacion":"El plan de evacuación debe considerar a personas con discapacidad, movilidad reducida, infantes y población no hispanohablante.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":38,"pagina_fin":39,"requiere_validacion":true},{"id":"L21442-A042-D01","articulo":"42","referencia":"Artículo 42","tipo":"articulo_permanente","categoria":"Seguridad, inspecciones y seguros","titulo":"Acta de ingreso urgente","texto":"En un ingreso de emergencia, debe quedar un registro formal de lo ocurrido.","explicacion":"El copropietario acompañante debe levantar acta detallada y se debe dejar copia dentro de la unidad afectada.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":40,"pagina_fin":40,"requiere_validacion":false},{"id":"L21442-A043-D01","articulo":"43","referencia":"Artículo 43","tipo":"articulo_permanente","categoria":"Seguridad, inspecciones y seguros","titulo":"Doble seguro","texto":"Tener un seguro hipotecario puede evitar duplicar ciertas coberturas, pero no elimina el seguro de bienes comunes.","explicacion":"La regulación debe permitir renunciar a la cobertura opcional de la unidad cuando exista otra póliza vigente, sin dejar de pagar cobertura común.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":40,"pagina_fin":41,"requiere_validacion":true},{"id":"L21442-A044-D01","articulo":"44","referencia":"Artículo 44","tipo":"articulo_permanente","categoria":"Resolución de conflictos","titulo":"Juez puede convocar asamblea","texto":"Un tribunal puede convocar asamblea si los órganos de administración no lo hacen.","explicacion":"Si la presidencia o la administración no convoca cuando corresponde, un juez puede citar una asamblea bajo requisitos legales.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":41,"pagina_fin":42,"requiere_validacion":false},{"id":"L21442-A047-D01","articulo":"47","referencia":"Artículo 47","tipo":"articulo_permanente","categoria":"Resolución de conflictos","titulo":"Acta de mediación municipal","texto":"Un acuerdo de mediación municipal puede incorporarse formalmente al libro de actas del condominio.","explicacion":"Los acuerdos alcanzados ante la municipalidad deben constar en acta autorizada por el secretario municipal.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":43,"pagina_fin":43,"requiere_validacion":false},{"id":"L21442-A059-D01","articulo":"59","referencia":"Artículo 59","tipo":"articulo_permanente","categoria":"Exigencias urbanas y de construcción","titulo":"Paso de emergencia libre","texto":"No se deben colocar objetos que bloqueen el paso de ambulancias y Bomberos.","explicacion":"El administrador responde personalmente de mantener condiciones para acceso y operación de vehículos de emergencia.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":48,"pagina_fin":48,"requiere_validacion":false},{"id":"L21442-A059-D02","articulo":"59","referencia":"Artículo 59","tipo":"articulo_permanente","categoria":"Exigencias urbanas y de construcción","titulo":"Cierros opacos","texto":"Los cierres completamente opacos hacia la calle están sujetos a limitaciones legales.","explicacion":"En deslindes hacia vialidades, los tramos de cierro opaco tienen condiciones; uno de sus límites es un máximo de 50 metros lineales por tramo.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":48,"pagina_fin":48,"requiere_validacion":false},{"id":"L21442-A060-D01","articulo":"60","referencia":"Artículo 60","tipo":"articulo_permanente","categoria":"Exigencias urbanas y de construcción","titulo":"Estacionamientos accesibles","texto":"Una plaza accesible asignada temporalmente debe quedar disponible cuando la solicita una persona que cumple los requisitos.","explicacion":"Las plazas reservadas para personas con discapacidad deben asignarse a quienes acrediten esa condición y las requieran; ciertos usos temporales terminan cuando son necesarias.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":48,"pagina_fin":50,"requiere_validacion":true},{"id":"L21442-A060-D02","articulo":"60","referencia":"Artículo 60","tipo":"articulo_permanente","categoria":"Exigencias urbanas y de construcción","titulo":"Bicicletas en proyectos","texto":"La planificación de estacionamientos en condominios también debe considerar bicicletas.","explicacion":"La dotación de estacionamientos de condominios debe considerar automóviles y bicicletas conforme a la normativa aplicable.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":48,"pagina_fin":50,"requiere_validacion":true},{"id":"L21442-A068-D01","articulo":"68","referencia":"Artículo 68","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Apoyo para ascensores","texto":"Un proyecto de ascensores puede ser elegible para ciertos programas dirigidos a condominios sociales.","explicacion":"Los recursos públicos contemplados en este artículo pueden apoyar instalación, certificación y mantención de equipos de circulación vertical.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":53,"pagina_fin":54,"requiere_validacion":false},{"id":"L21442-A068-D02","articulo":"68","referencia":"Artículo 68","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Formación de comité","texto":"Existen programas públicos orientados también a enseñar cómo administrar mejor un condominio social.","explicacion":"Entre las finalidades de apoyos públicos figuran capacitaciones para comités y administradores y acciones de convivencia.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":53,"pagina_fin":54,"requiere_validacion":false},{"id":"L21442-A070-D01","articulo":"70","referencia":"Artículo 70","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Proyectos de 160 unidades","texto":"Varios condominios sociales contiguos pueden tramitarse conjuntamente sin perder su independencia jurídica.","explicacion":"Varios condominios sociales independientes en un terreno pueden tramitarse de modo coordinado, pero cada uno debe tener sus órganos y reglamento.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":54,"pagina_fin":55,"requiere_validacion":true},{"id":"L21442-A073-D01","articulo":"73","referencia":"Artículo 73","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Trámite en 30 días","texto":"Ciertas gestiones notariales y conservatorias de condominios sociales tienen plazo máximo de 30 días.","explicacion":"Las actuaciones de notarios, conservadores y archiveros requeridas por viviendas sociales bajo este artículo deben practicarse en un máximo de treinta días.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":56,"pagina_fin":56,"requiere_validacion":false},{"id":"L21442-A079-D01","articulo":"79","referencia":"Artículo 79","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Densidad de 220 viviendas/ha","texto":"La excepción de densificación de hasta 12 viviendas incluye una densidad neta máxima de 220 viviendas por hectárea.","explicacion":"En los casos MINVU que permiten hasta doce unidades de densificación predial, la densidad neta no puede superar 220 viviendas por hectárea.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":57,"pagina_fin":58,"requiere_validacion":false},{"id":"L21442-A084-D01","articulo":"84","referencia":"Artículo 84","tipo":"articulo_permanente","categoria":"Registro Nacional de Administradores","titulo":"Formación especializada","texto":"Administrar profesionalmente un condominio exige conocimientos tanto técnicos como laborales y financieros.","explicacion":"El curso o certificación laboral de administradores remunerados debe acreditar conocimientos sobre seguridad, trabajo, finanzas y conflictos.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":59,"pagina_fin":59,"requiere_validacion":false},{"id":"L21442-A087-D01","articulo":"87","referencia":"Artículo 87","tipo":"articulo_permanente","categoria":"Infracciones, sanciones y reclamos","titulo":"Reincidencia grave","texto":"La reincidencia puede elevar la clasificación de una falta del administrador.","explicacion":"Reincidir en una infracción grave en un período de tres años puede convertirla en gravísima.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":60,"pagina_fin":61,"requiere_validacion":true},{"id":"L21442-A088-D01","articulo":"88","referencia":"Artículo 88","tipo":"articulo_permanente","categoria":"Infracciones, sanciones y reclamos","titulo":"Multa para falta menos grave","texto":"Una infracción menos grave del administrador también puede terminar en multa administrativa.","explicacion":"Las infracciones menos graves se sancionan con amonestación escrita y/o multa de 1 a 4 UTM.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":61,"pagina_fin":61,"requiere_validacion":true},{"id":"L21442-A090-D01","articulo":"90","referencia":"Artículo 90","tipo":"articulo_permanente","categoria":"Infracciones, sanciones y reclamos","titulo":"Qué acompaña una reclamación","texto":"Guardar actas, comunicaciones y respaldos facilita presentar una reclamación fundada.","explicacion":"Una reclamación ante la SEREMI debe precisar la acción u omisión y adjuntar antecedentes que la fundamenten.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":62,"pagina_fin":62,"requiere_validacion":false},{"id":"L21442-A098-D01","articulo":"98","referencia":"Artículo 98","tipo":"articulo_permanente","categoria":"Disposiciones finales","titulo":"Dato del reglamento en registro","texto":"El registro de condominios habitacionales permite relacionar el edificio con su reglamento formalizado.","explicacion":"El registro habitacional consigna antecedentes del reglamento de copropiedad y su inscripción conservatoria.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":64,"pagina_fin":64,"requiere_validacion":false},{"id":"L21442-A102-D01","articulo":"102","referencia":"Artículo 102","tipo":"articulo_permanente","categoria":"Disposiciones finales","titulo":"Asamblea anual de residentes","texto":"Aunque todavía se hayan vendido pocas unidades, los residentes tienen derecho a recibir información anual del funcionamiento.","explicacion":"Con menos del 33% de derechos del condominio enajenados, debe convocarse anualmente una asamblea de residentes con fines informativos.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":65,"pagina_fin":66,"requiere_validacion":false},{"id":"L21442-A001-D01","articulo":"1","referencia":"Artículo 1","tipo":"articulo_permanente","categoria":"Fundamentos y definiciones","titulo":"Copropiedad rural excepcional","texto":"No toda parcelación rural es un condominio sometido a la Ley 21.442.","explicacion":"Los condominios pueden emplazarse en área urbana y excepcionalmente en zona rural con autorizaciones y exigencias especiales.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":1,"pagina_fin":3,"requiere_validacion":false},{"id":"L21442-A002-D03","articulo":"2","referencia":"Artículo 2","tipo":"articulo_permanente","categoria":"Fundamentos y definiciones","titulo":"Qué es un copropietario hábil","texto":"Estar al día en todas las obligaciones económicas importa para ejercer ciertos derechos comunitarios.","explicacion":"La ley llama copropietario hábil a quien está al día en todas sus obligaciones económicas con el condominio.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":3,"pagina_fin":6,"requiere_validacion":false},{"id":"L21442-A004-D01","articulo":"4","referencia":"Artículo 4","tipo":"articulo_permanente","categoria":"Derechos y obligaciones","titulo":"Derechos del arrendatario","texto":"El uso legítimo de bienes comunes no está reservado exclusivamente al dueño de la unidad.","explicacion":"El arrendatario y otros ocupantes también tienen derecho a utilizar bienes comunes conforme a reglamento, sin perturbar derechos ajenos.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":6,"pagina_fin":7,"requiere_validacion":false},{"id":"L21442-A006-D03","articulo":"6","referencia":"Artículo 6","tipo":"articulo_permanente","categoria":"Derechos y obligaciones","titulo":"Declaración de deuda en escritura","texto":"Al vender, el propietario debe declarar en la escritura las obligaciones económicas pendientes.","explicacion":"Quien vende una unidad debe declarar en la escritura pública si está al día en las obligaciones económicas o indicar lo adeudado.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":7,"pagina_fin":8,"requiere_validacion":false},{"id":"L21442-A008-D03","articulo":"8","referencia":"Artículo 8","tipo":"articulo_permanente","categoria":"Reglamento de copropiedad","titulo":"Reglamento obliga a ocupantes","texto":"Un arrendatario también debe cumplir el reglamento de copropiedad.","explicacion":"Las normas del reglamento vinculan a propietarios, futuros adquirentes y ocupantes a cualquier título.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":8,"pagina_fin":10,"requiere_validacion":false},{"id":"L21442-A008-D04","articulo":"8","referencia":"Artículo 8","tipo":"articulo_permanente","categoria":"Reglamento de copropiedad","titulo":"Reglamento inscrito","texto":"Un reglamento aprobado en una reunión debe formalizarse e inscribirse conforme a la ley.","explicacion":"El reglamento y sus modificaciones deben constar en escritura pública e inscribirse en el registro conservatorio correspondiente.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":8,"pagina_fin":10,"requiere_validacion":false},{"id":"L21442-A010-D01","articulo":"10","referencia":"Artículo 10","tipo":"articulo_permanente","categoria":"Reglamento de copropiedad","titulo":"Quién puede impugnar","texto":"No cualquier desacuerdo con el reglamento basta para obtener su nulidad judicial.","explicacion":"La acción de nulidad se sujeta a requisitos: el copropietario debe sufrir perjuicio reparable mediante nulidad y se regulan inhabilidades para demandar.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":12,"pagina_fin":13,"requiere_validacion":false},{"id":"L21442-A014-D03","articulo":"14","referencia":"Artículo 14","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Cambio de cobertura de seguro","texto":"Modificar coberturas relevantes del seguro del condominio puede requerir asamblea extraordinaria.","explicacion":"Ciertos cambios en el seguro colectivo que alteren riesgos cubiertos deben tratarse en sesión extraordinaria de la asamblea.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":13,"pagina_fin":15,"requiere_validacion":false},{"id":"L21442-A015-D06","articulo":"15","referencia":"Artículo 15","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Quórum reforzado del 66%","texto":"Hay acuerdos para los cuales reunir a pocos asistentes no basta: exigen 66% de derechos.","explicacion":"Para las materias sujetas a mayoría reforzada, la constitución y aprobación exigen derechos equivalentes al 66% del condominio.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":15,"pagina_fin":25,"requiere_validacion":true},{"id":"L21442-A015-D07","articulo":"15","referencia":"Artículo 15","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Quórum ordinario del 33%","texto":"Una asamblea ordinaria necesita representación mínima del 33% de los derechos del condominio.","explicacion":"La constitución de una asamblea ordinaria requiere asistentes que representen al menos el 33% de derechos; los acuerdos requieren mayoría absoluta de asistentes.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":15,"pagina_fin":25,"requiere_validacion":true},{"id":"L21442-A015-D08","articulo":"15","referencia":"Artículo 15","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Notario en acuerdos reforzados","texto":"Algunos acuerdos de asamblea exigen la intervención formal de un notario.","explicacion":"Para sesiones con mayoría reforzada y determinados cambios reglamentarios debe asistir notario, que certificará el acta.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":15,"pagina_fin":25,"requiere_validacion":true},{"id":"L21442-A017-D03","articulo":"17","referencia":"Artículo 17","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Mandato de tres años","texto":"Un comité de administración no puede tener un mandato único de más de tres años.","explicacion":"La asamblea fija el período del comité, que no puede exceder tres años, sin perjuicio de reelección.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":26,"pagina_fin":27,"requiere_validacion":false},{"id":"L21442-A018-D01","articulo":"18","referencia":"Artículo 18","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Remoción del administrador","texto":"El administrador no tiene un mandato perpetuo: la asamblea puede removerlo.","explicacion":"La asamblea puede remover al administrador en cualquier momento por acuerdo legalmente adoptado.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":27,"pagina_fin":28,"requiere_validacion":false},{"id":"L21442-A020-D04","articulo":"20","referencia":"Artículo 20","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Contratación de trabajadores","texto":"La contratación y desvinculación del personal del condominio no siempre depende solo del administrador.","explicacion":"El administrador requiere acuerdo previo del comité para contratar o terminar contratos de trabajo, salvo delegación legal de la asamblea.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":28,"pagina_fin":30,"requiere_validacion":true},{"id":"L21442-A022-D02","articulo":"22","referencia":"Artículo 22","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Previsión de recargo","texto":"Una planificación anual responsable anticipa si subirán los gastos comunes y por qué.","explicacion":"El presupuesto anual debe informar si se proyecta necesitar recargos en gastos comunes para cubrir obligaciones.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":30,"pagina_fin":31,"requiere_validacion":false},{"id":"L21442-A024-D01","articulo":"24","referencia":"Artículo 24","tipo":"articulo_permanente","categoria":"Órganos, asambleas y administración","titulo":"Excepción de edificio único","texto":"Un único edificio con más de 200 viviendas puede acogerse a una excepción de subadministraciones.","explicacion":"La ley exceptúa de subadministraciones a un condominio formado por una sola edificación colectiva de más de 200 unidades, pero exige bienes comunes diferenciados.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":32,"pagina_fin":32,"requiere_validacion":false},{"id":"L21442-A026-D02","articulo":"26","referencia":"Artículo 26","tipo":"articulo_permanente","categoria":"Propiedad, bienes comunes y uso","titulo":"Obras de gas en bienes comunes","texto":"Modificar instalaciones colectivas de gas exige personal autorizado y formalidades especiales.","explicacion":"Las alteraciones de gas y ventilación comprendidas por la norma deben ejecutarse por autorizados SEC, con acuerdos y permisos cuando corresponda.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":33,"pagina_fin":34,"requiere_validacion":false},{"id":"L21442-A028-D01","articulo":"28","referencia":"Artículo 28","tipo":"articulo_permanente","categoria":"Propiedad, bienes comunes y uso","titulo":"Aportes por uso exclusivo","texto":"El uso exclusivo de un bien común puede tener un costo destinado al fondo de reserva.","explicacion":"El uso y goce exclusivo de determinados bienes comunes puede obligar a una suma única o pagos periódicos para el fondo de reserva.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":35,"pagina_fin":35,"requiere_validacion":false},{"id":"L21442-A029-D01","articulo":"29","referencia":"Artículo 29","tipo":"articulo_permanente","categoria":"Propiedad, bienes comunes y uso","titulo":"Uso exclusivo no habilita construcción","texto":"Tener un patio de uso exclusivo no equivale a permiso para techarlo.","explicacion":"Para construir o cambiar el destino de un bien común asignado en uso exclusivo se requiere acuerdo extraordinario reforzado y permiso cuando proceda.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":35,"pagina_fin":35,"requiere_validacion":false},{"id":"L21442-A033-D01","articulo":"33","referencia":"Artículo 33","tipo":"articulo_permanente","categoria":"Gastos comunes, cobranza y fondos","titulo":"Cambios en autorizados bancarios","texto":"Un cambio de firma bancaria comunitaria debe respaldarse legalmente.","explicacion":"La actualización de personas habilitadas para operar cuentas debe acreditarse ante el banco con el acta correspondiente reducida a escritura pública.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":36,"pagina_fin":36,"requiere_validacion":false},{"id":"L21442-A040-D04","articulo":"40","referencia":"Artículo 40","tipo":"articulo_permanente","categoria":"Seguridad, inspecciones y seguros","titulo":"Antes, durante y después","texto":"Un plan de emergencia no consiste solo en escapar: también debe prever prevención y recuperación.","explicacion":"El plan de emergencia debe contemplar acciones previas, durante y posteriores a siniestros, con énfasis en alerta y evacuación.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":38,"pagina_fin":39,"requiere_validacion":true},{"id":"L21442-A043-D02","articulo":"43","referencia":"Artículo 43","tipo":"articulo_permanente","categoria":"Seguridad, inspecciones y seguros","titulo":"Cobertura sísmica adicional","texto":"Seguro contra incendio y seguro contra sismo no son necesariamente la misma cobertura.","explicacion":"El seguro colectivo contra incendio no implica automáticamente cobertura de sismo o salida de mar, que pueden ser complementarias.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":40,"pagina_fin":41,"requiere_validacion":true},{"id":"L21442-A048-D01","articulo":"48","referencia":"Artículo 48","tipo":"articulo_permanente","categoria":"Constitución legal de condominios","titulo":"Venta de proyectos en construcción","texto":"La promesa de venta de una unidad puede anteceder a su recepción; la transferencia está sujeta a requisitos legales.","explicacion":"La enajenación de unidades en proyectos aprobados debe esperar la recepción de las obras que correspondan, sin perjuicio de promesas de compraventa.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":43,"pagina_fin":45,"requiere_validacion":false},{"id":"L21442-A052-D01","articulo":"52","referencia":"Artículo 52","tipo":"articulo_permanente","categoria":"Constitución legal de condominios","titulo":"Cambio de régimen y acreedores","texto":"Una comunidad no puede ignorar derechos hipotecarios al intentar terminar el régimen de copropiedad.","explicacion":"Al solicitar dejar sin efecto un régimen se deben cumplir normas y, si corresponde, recabar autorizaciones de acreedores hipotecarios.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":46,"pagina_fin":46,"requiere_validacion":false},{"id":"L21442-A060-D03","articulo":"60","referencia":"Artículo 60","tipo":"articulo_permanente","categoria":"Exigencias urbanas y de construcción","titulo":"Visitas no exclusivas","texto":"Un estacionamiento de visitas no debería convertirse en estacionamiento privado permanente.","explicacion":"Los estacionamientos de visita tienen carácter común y no pueden venderse ni asignarse exclusivamente a unidades.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":48,"pagina_fin":50,"requiere_validacion":true},{"id":"L21442-A064-D01","articulo":"64","referencia":"Artículo 64","tipo":"articulo_permanente","categoria":"Obras, cambios y subdivisión","titulo":"Subdivisión impulsada por municipalidad","texto":"La municipalidad puede proponer subdividir un condominio social, sin omitir la votación de copropietarios.","explicacion":"La Dirección de Obras Municipales puede proponer dividir un condominio de viviendas sociales, pero se requiere la aprobación de derechos exigida por la ley.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":50,"pagina_fin":51,"requiere_validacion":false},{"id":"L21442-A068-D03","articulo":"68","referencia":"Artículo 68","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Administrador provisional excepcional","texto":"Algunos condominios sociales sin administrador pueden recibir una designación provisional pública.","explicacion":"Ciertos órganos públicos pueden designar una sola vez un administrador provisional para un condominio social sin administrador, con reemplazo definitivo dentro de un año.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":53,"pagina_fin":54,"requiere_validacion":false},{"id":"L21442-A070-D02","articulo":"70","referencia":"Artículo 70","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Condominios independientes","texto":"Varios condominios construidos juntos no necesariamente forman una sola comunidad jurídica.","explicacion":"En conjuntos de varios condominios sociales cada uno debe conservar su propio reglamento, órganos y acceso en los términos legales.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":54,"pagina_fin":55,"requiere_validacion":true},{"id":"L21442-A080-D01","articulo":"80","referencia":"Artículo 80","tipo":"articulo_permanente","categoria":"Viviendas sociales, interés público y densificación","titulo":"Reglamento tipo en densificación","texto":"Los condominios de densificación predial tienen una regla especial si no cuentan con reglamento propio.","explicacion":"A falta de reglamento, los condominios de densificación predial aplican el reglamento tipo, sin necesidad de inscribirlo en el Conservador.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":58,"pagina_fin":58,"requiere_validacion":false},{"id":"L21442-A090-D02","articulo":"90","referencia":"Artículo 90","tipo":"articulo_permanente","categoria":"Infracciones, sanciones y reclamos","titulo":"Arrendatarios reclamantes","texto":"La ley contempla legitimación de ciertos arrendatarios para reclamar formalmente ante la SEREMI.","explicacion":"Un porcentaje mínimo de arrendatarios, definido en el reglamento de la ley, también puede presentar reclamaciones contra administradores ante la SEREMI.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":62,"pagina_fin":62,"requiere_validacion":false},{"id":"L21442-A098-D02","articulo":"98","referencia":"Artículo 98","tipo":"articulo_permanente","categoria":"Disposiciones finales","titulo":"Registro no es voluntario","texto":"Existe un registro institucional específico para condominios con viviendas.","explicacion":"Los condominios habitacionales están contemplados en un registro bajo responsabilidad de la Secretaría Ejecutiva de Condominios.","precaucion":"Consulta la lección del artículo para conocer requisitos, condiciones y excepciones.","automatico":true,"pagina_inicio":64,"pagina_fin":64,"requiere_validacion":false}]'),n={version_fuente:e,url_oficial:a,aviso:i,contenidos:o};export{n as b};
